const int LED    = 9;
const int BUTTON = 2;

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);   // button shorts to GND when pressed
  Serial.begin(9600);
  randomSeed(analogRead(A0));      // different random sequence each power-up
}

void loop() {
  Serial.println("Get ready ...");
  delay(random(2000, 5000));       // random 2-5 second pause

  digitalWrite(LED, HIGH);         // GO
  unsigned long start = millis();

  while (digitalRead(BUTTON) == HIGH) {
    // wait for the button press
  }

  unsigned long reaction = millis() - start;
  digitalWrite(LED, LOW);

  Serial.print("Your reaction: ");
  Serial.print(reaction);
  Serial.println(" ms");
  Serial.println();
  delay(2000);
}

/*
 * XIAO Chip Temperature - tiny web page
 * -------------------------------------
 * The XIAO ESP32-C3 reads its own internal chip die temperature and
 * serves a single web page that shows it. The browser auto-refreshes
 * the whole page every 5 seconds using an HTML meta refresh tag, so
 * there is no JavaScript at all.
 *
 * IMPORTANT: this is the CHIP temperature, not the room temperature.
 * The ESP32-C3 warms itself while running WiFi, so the number will
 * typically read 40 to 55 C even in a cool room. To measure the room,
 * add a real external sensor (DHT22 or BME280) later - that is the
 * "Things to change once it works" step.
 *
 * Before uploading: replace PASSWORD_HERE with the real GeeFam WiFi
 * password on the line marked below.
 *
 * Board: XIAO_ESP32C3   |   Baud: 115200
 */

#include <WiFi.h>
#include <WebServer.h>

// ----- WiFi credentials -----
const char* WIFI_SSID     = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";   // <-- edit this line before flashing

// One web server listening on the standard HTTP port.
WebServer server(80);

// Build the HTML page that the browser sees when it visits "/".
// The <meta http-equiv='refresh' content='5'> tag tells the browser to
// reload the whole page every 5 seconds. No JavaScript needed.
void handleRoot() {
  float tempC = temperatureRead();   // provided by the ESP32 Arduino core

  String page = "<!DOCTYPE html><html><head><meta charset='utf-8'>";
  page += "<meta name='viewport' content='width=device-width,initial-scale=1'>";
  page += "<meta http-equiv='refresh' content='5'>";
  page += "<title>XIAO Chip Temperature</title>";
  page += "<style>";
  page += "body{font-family:system-ui,sans-serif;background:#0f172a;color:#e2e8f0;";
  page += "margin:0;padding:32px;text-align:center;}";
  page += "h1{font-weight:500;margin:0 0 8px;}";
  page += ".now{font-size:72px;font-weight:600;color:#10b981;margin:16px 0;}";
  page += ".warn{color:#fbbf24;background:#1e293b;border-radius:8px;";
  page += "padding:12px 16px;max-width:480px;margin:24px auto;font-size:14px;}";
  page += ".foot{margin-top:16px;color:#64748b;font-size:13px;}";
  page += "</style></head><body>";
  page += "<h1>XIAO Chip Temperature</h1>";
  page += "<div class='now'>";
  page += String(tempC, 1);
  page += " C</div>";
  page += "<div class='warn'><b>Note:</b> this is the temperature of the ";
  page += "ESP32-C3 chip itself, NOT the room. The chip self-heats while ";
  page += "running WiFi, so this number runs warm.</div>";
  page += "<div class='foot'>Page auto-refreshes every 5 seconds.</div>";
  page += "</body></html>";

  server.send(200, "text/html", page);
}

void handleNotFound() {
  server.send(404, "text/plain", "Not found");
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("XIAO Chip Temperature starting...");

  // Join the GeeFam WiFi as a normal client (station mode).
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.print("Connecting to ");
  Serial.println(WIFI_SSID);

  unsigned long startAttempt = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - startAttempt < 30000UL) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("Connected. Open this address in a browser: http://");
    Serial.println(WiFi.localIP());
    Serial.print("RSSI: ");
    Serial.println(WiFi.RSSI());
  } else {
    Serial.println("WiFi failed - check SSID/password and try again.");
  }

  // Register the one and only page, then start the server.
  server.on("/", handleRoot);
  server.onNotFound(handleNotFound);
  server.begin();
  Serial.println("Web server listening on port 80.");
}

void loop() {
  // If WiFi dropped, try to reconnect quietly every 5 seconds.
  if (WiFi.status() != WL_CONNECTED) {
    static unsigned long lastReconnectMs = 0;
    if (millis() - lastReconnectMs > 5000UL) {
      lastReconnectMs = millis();
      Serial.println("WiFi disconnected - retrying.");
      WiFi.disconnect();
      WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
    }
  }

  // Hand any incoming browser requests to the handlers above.
  server.handleClient();
}

// Theremin Lite
// Wave your hand above the HC-SR04 ultrasonic sensor and the red LED
// blinks faster the closer you get. Like a Geiger counter chasing your palm.
//
// Board: ESP32 Dev Module (or NodeMCU-32S)
// Serial: 115200 baud

// ---- Pin map (must match the wiring diagram) ----
const int PIN_TRIG = 5;    // ESP32 output -> sensor Trig
const int PIN_ECHO = 18;   // sensor Echo -> voltage divider -> ESP32 input
const int PIN_LED  = 19;   // ESP32 output -> 220R -> LED anode

// ---- Tuning knobs ----
const float DIST_MIN_CM   = 3.0f;    // hand right above the sensor
const float DIST_MAX_CM   = 50.0f;   // arm's length away
const int   BLINK_FAST_MS = 30;      // shortest on-time when very close
const int   BLINK_SLOW_MS = 600;     // longest on-time when far / no hand

// Echo timeout. Shorter = snappier response when nothing is in front of the
// sensor (the loop won't sit waiting for a phantom echo). 12000us ~= 2 metres
// of round-trip, which is plenty for hand-waving range.
const unsigned long ECHO_TIMEOUT_US = 12000UL;

// Measure distance in centimetres. Returns -1.0f if no echo came back.
float readDistanceCm() {
  // Send a clean 10-microsecond HIGH pulse on Trig.
  digitalWrite(PIN_TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);

  // pulseIn waits for Echo to go HIGH, then times how long it stays HIGH.
  unsigned long durationUs = pulseIn(PIN_ECHO, HIGH, ECHO_TIMEOUT_US);
  if (durationUs == 0) {
    return -1.0f; // timeout - nothing in range
  }

  // Speed of sound is ~343 m/s = 0.0343 cm/us. Divide by 2 for the round trip.
  return (durationUs * 0.0343f) / 2.0f;
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Theremin Lite ready. Wave your hand!");

  pinMode(PIN_TRIG, OUTPUT);
  pinMode(PIN_ECHO, INPUT);
  pinMode(PIN_LED,  OUTPUT);

  digitalWrite(PIN_TRIG, LOW);
  digitalWrite(PIN_LED,  LOW);
}

void loop() {
  float cm = readDistanceCm();

  // Decide how long the LED should be on, then off.
  int blinkMs;
  if (cm < 0) {
    // No echo - treat it like "nothing nearby", slow heartbeat.
    blinkMs = BLINK_SLOW_MS;
    Serial.println("distance: (no echo)");
  } else {
    // Clamp to the band we care about.
    if (cm < DIST_MIN_CM) cm = DIST_MIN_CM;
    if (cm > DIST_MAX_CM) cm = DIST_MAX_CM;

    // Simple linear interpolation (lerp):
    // at DIST_MIN_CM -> BLINK_FAST_MS, at DIST_MAX_CM -> BLINK_SLOW_MS,
    // and a straight line between the two.
    float t = (cm - DIST_MIN_CM) / (DIST_MAX_CM - DIST_MIN_CM);
    blinkMs = (int)(BLINK_FAST_MS + t * (BLINK_SLOW_MS - BLINK_FAST_MS));

    Serial.print("distance: ");
    Serial.print(cm, 1);
    Serial.print(" cm    blink: ");
    Serial.print(blinkMs);
    Serial.println(" ms");
  }

  // One blink at the chosen rate.
  digitalWrite(PIN_LED, HIGH);
  delay(blinkMs);
  digitalWrite(PIN_LED, LOW);
  delay(blinkMs);
}

// Don't-Touch-The-Wire steady-hand maze
// Board: ESP32 NodeMCU-32S
// 7-segment display: TM1637 4-digit module (install "TM1637" library by Avishay Orpaz)
//
// How it works:
//   - The bent maze wire is connected to PIN_WIRE with an internal pull-up.
//   - The wand loop is connected to GND.
//   - Touching the wand to the maze pulls PIN_WIRE LOW -> that's a strike.
//   - We only count a strike on a fresh HIGH->LOW transition (edge detection),
//     so holding the wand against the wire does NOT keep racking up strikes.
//   - Green LED is on while the player is clear; red LED is on while touching.
//   - The 4-digit display shows the strike count. Press the button to reset to 0.

#include <Arduino.h>
#include <TM1637Display.h>

// ---- Pin map (matches the wiring diagram) ----
const int PIN_WIRE   = 23;  // maze wire contact (INPUT_PULLUP)
const int PIN_LED_R  = 18;  // red LED (touching indicator)
const int PIN_LED_G  = 19;  // green LED (all-clear indicator)
const int PIN_BTN    = 5;   // reset button (INPUT_PULLUP). GPIO 5 is a strapping pin;
                            // idle-HIGH (released) matches the boot-time requirement, so this is safe.
const int PIN_CLK    = 22;  // TM1637 CLK
const int PIN_DIO    = 21;  // TM1637 DIO

// ---- Tuning ----
const int MAX_STRIKES = 9999;  // 4-digit display ceiling

// ---- State ----
TM1637Display display(PIN_CLK, PIN_DIO);
int strikes = 0;
int lastWireState = HIGH;  // remembers what the wire pin was last loop, so we can spot HIGH->LOW edges

void showScore() {
  display.showNumberDec(strikes, false);  // false = don't pad with leading zeros
}

void resetGame() {
  strikes = 0;
  showScore();
  digitalWrite(PIN_LED_R, LOW);
  digitalWrite(PIN_LED_G, HIGH);
  Serial.println("Reset - new round");
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println("Steady-hand maze: starting up");

  pinMode(PIN_WIRE,  INPUT_PULLUP);
  pinMode(PIN_BTN,   INPUT_PULLUP);
  pinMode(PIN_LED_R, OUTPUT);
  pinMode(PIN_LED_G, OUTPUT);

  display.setBrightness(5);  // 0-7
  resetGame();
}

void loop() {
  // ---- 1. Read the maze contact ----
  // LOW means the wand is touching the wire.
  int wireState = digitalRead(PIN_WIRE);

  // Edge detection: count a strike ONLY on the moment of contact (HIGH -> LOW).
  // Holding the wand against the wire stays LOW, so no extra strikes pile up.
  if (lastWireState == HIGH && wireState == LOW) {
    delay(20);  // tiny pause then re-read, so contact bounce doesn't double-count
    if (digitalRead(PIN_WIRE) == LOW) {
      if (strikes < MAX_STRIKES) strikes++;
      showScore();
      Serial.print("Strike! Total = ");
      Serial.println(strikes);
    }
  }
  lastWireState = wireState;

  // ---- 2. LEDs follow the wire state directly (no timers) ----
  // Touching -> red on, green off. Not touching -> green on, red off.
  if (wireState == LOW) {
    digitalWrite(PIN_LED_R, HIGH);
    digitalWrite(PIN_LED_G, LOW);
  } else {
    digitalWrite(PIN_LED_R, LOW);
    digitalWrite(PIN_LED_G, HIGH);
  }

  // ---- 3. Read the reset button (simple delay-based debounce) ----
  // Nothing time-critical happens during a reset press, so a small delay is fine.
  if (digitalRead(PIN_BTN) == LOW) {
    delay(50);
    if (digitalRead(PIN_BTN) == LOW) {
      resetGame();
      // wait for the user to let go so we don't reset repeatedly
      while (digitalRead(PIN_BTN) == LOW) {
        delay(10);
      }
    }
  }
}

// Temperature Mood Dial
// Board: Seeed XIAO ESP32-C3
// Reads the DHT11 every ~2 seconds and sweeps an SG90 servo
// across a hand-drawn gauge based on the temperature.
//
// Libraries needed (install via Arduino IDE Library Manager):
//   - "DHT sensor library" by Adafruit
//   - "Adafruit Unified Sensor" (dependency of the above)
//   - "ESP32Servo" by Kevin Harrington / John K. Bennett
//
// Wiring (matches the Mermaid diagram):
//   DHT11 VCC  -> XIAO 3V3   (NOT 5V - keeps the DATA line at 3.3V so
//                             it is safe for the XIAO's 3.3V GPIO)
//   DHT11 GND  -> XIAO GND
//   DHT11 DATA -> XIAO D2 (GPIO 4)
//   SG90 red   -> XIAO 5V    (servo genuinely needs 5V)
//   SG90 brown -> XIAO GND
//   SG90 orange-> XIAO D3 (GPIO 5)
//   470uF cap across the 5V and GND rails near the servo.

#include <DHT.h>
#include <ESP32Servo.h>

// ----- Pins -----
const int DHT_PIN   = 4;   // D2 on the XIAO silkscreen
const int SERVO_PIN = 5;   // D3 on the XIAO silkscreen

// ----- Sensor config -----
#define DHT_TYPE DHT11
DHT dht(DHT_PIN, DHT_TYPE);

// ----- Servo -----
Servo dialServo;

// ----- Temperature mapping -----
// Tune these to match your room. The needle sweeps the full
// 0..180 degrees between MIN_TEMP_C and MAX_TEMP_C.
// With 15..30 the five mood zones are evenly 3 C wide:
//   15-18 BRRR | 18-21 CHILLY | 21-24 NICE | 24-27 TOASTY | 27-30 LAVA
const float MIN_TEMP_C = 15.0;  // "BRRR"   end of the gauge
const float MAX_TEMP_C = 30.0;  // "LAVA"   end of the gauge

// ----- Smoothing -----
// We move the servo toward the target one step at a time so the
// needle glides instead of snapping. Tweak STEP_DEG for speed.
const int STEP_DEG       = 2;   // degrees per step
const int STEP_DELAY_MS  = 25;  // pause between steps
int currentAngle = 90;          // where the needle is right now
int targetAngle  = 90;          // where we want it to be

unsigned long lastReadMs = 0;
const unsigned long READ_INTERVAL_MS = 2000;  // DHT11 hates being read faster

int tempCtoAngle(float tempC) {
  // Clamp the temperature into the visible range.
  if (tempC < MIN_TEMP_C) tempC = MIN_TEMP_C;
  if (tempC > MAX_TEMP_C) tempC = MAX_TEMP_C;
  // Map Celsius -> 0..180 degrees. Multiplying by 100 keeps the
  // map() math integer-friendly.
  long t100   = (long)(tempC * 100.0);
  long min100 = (long)(MIN_TEMP_C * 100.0);
  long max100 = (long)(MAX_TEMP_C * 100.0);
  return (int)map(t100, min100, max100, 0, 180);
}

const char* moodFor(float tempC) {
  // Thresholds match the five 3 C zones drawn on the gauge.
  if (tempC < 18.0) return "BRRR";
  if (tempC < 21.0) return "CHILLY";
  if (tempC < 24.0) return "NICE";
  if (tempC < 27.0) return "TOASTY";
  return "LAVA";
}

void setup() {
  Serial.begin(115200);
  delay(500);
  Serial.println();
  Serial.println("Temperature Mood Dial booting...");

  dht.begin();

  // ESP32Servo wants a timer allocated explicitly.
  ESP32PWM::allocateTimer(0);
  dialServo.setPeriodHertz(50);            // SG90 expects 50 Hz
  dialServo.attach(SERVO_PIN, 500, 2400);  // typical SG90 pulse range

  // Greeting sweep so we know the servo is alive.
  for (int a = 0; a <= 180; a += 5) {
    dialServo.write(a);
    delay(15);
  }
  for (int a = 180; a >= 0; a -= 5) {
    dialServo.write(a);
    delay(15);
  }
  dialServo.write(currentAngle);
  delay(300);
}

void loop() {
  unsigned long now = millis();

  // 1) Read the DHT11 every couple of seconds.
  if (now - lastReadMs >= READ_INTERVAL_MS) {
    lastReadMs = now;
    float tempC = dht.readTemperature();
    float hum   = dht.readHumidity();

    if (isnan(tempC) || isnan(hum)) {
      Serial.println("DHT11 read failed - check wiring.");
    } else {
      targetAngle = tempCtoAngle(tempC);
      Serial.print("Temp: ");
      Serial.print(tempC, 0);          // DHT11 only reports whole degrees
      Serial.print(" C  Humidity: ");
      Serial.print(hum, 0);
      Serial.print(" %  Mood: ");
      Serial.print(moodFor(tempC));
      Serial.print("  ->  angle ");
      Serial.print(targetAngle);
      Serial.println(" deg");
    }
  }

  // 2) Nudge the servo toward the target one tiny step at a time.
  if (currentAngle != targetAngle) {
    if (currentAngle < targetAngle) {
      currentAngle += STEP_DEG;
      if (currentAngle > targetAngle) currentAngle = targetAngle;
    } else {
      currentAngle -= STEP_DEG;
      if (currentAngle < targetAngle) currentAngle = targetAngle;
    }
    dialServo.write(currentAngle);
    delay(STEP_DELAY_MS);
  }
}

// Shake-to-roll D6 dice (ESP32 NodeMCU-32S)
// Hardware: ESP32 + SW-420 vibration switch + TM1637 4-digit display + 1 green LED
//
// Library required: "TM1637" by Avishay Orpaz
//   Arduino IDE -> Tools -> Manage Libraries -> search "TM1637" -> install
//
// What it does:
//   - Sits idle with the display blanked
//   - When you shake the breadboard, the vibration switch fires
//   - The green LED turns on and the display flickers through random faces
//   - The flicker slows down, then stops on a random number 1..6
//   - The green LED turns off; the result stays on screen until next shake

#include <Arduino.h>
#include <TM1637Display.h>

// ----- Pin assignments (these MUST match the wiring diagram) -----
// GPIO27 is a safe general-purpose pin (NOT a boot strapping pin), so the
// SW-420's signal can't accidentally affect how the ESP32 boots.
const int PIN_SHAKE   = 27;  // SW-420 DO  -> GPIO27
const int PIN_LED     = 26;  // Green LED  -> GPIO26 (through 220R)
const int PIN_TM_CLK  = 18;  // TM1637 CLK -> GPIO18
const int PIN_TM_DIO  = 19;  // TM1637 DIO -> GPIO19

// ----- Display setup -----
TM1637Display display(PIN_TM_CLK, PIN_TM_DIO);

// ----- Roll / cooldown state -----
// After a roll we ignore the sensor briefly so the leftover vibration
// from your hand hitting the table doesn't immediately re-roll.
unsigned long rollCooldownUntil = 0;
const unsigned long ROLL_COOLDOWN_MS = 1500;

void showNumber(int n) {
  // showNumberDec prints a number on the display. The "false" means
  // "don't pad with leading zeros". The "1" prints one digit only.
  // The final "3" puts that digit in the rightmost position (index 3).
  display.showNumberDec(n, false, 1, 3);
}

void clearDisplay() {
  uint8_t blank[4] = { 0, 0, 0, 0 };
  display.setSegments(blank);
}

int rollDice() {
  // esp_random() is the ESP32's hardware random number generator.
  // We take the result modulo 6 (so 0..5) and add 1 to get 1..6.
  return (int)(esp_random() % 6) + 1;
}

void doRollAnimation() {
  digitalWrite(PIN_LED, HIGH);

  // Shorter delays at the start, longer ones at the end:
  // that's what makes it feel like a real die losing energy.
  int delays[11] = { 60, 60, 60, 60, 80, 100, 130, 170, 220, 300, 400 };
  int steps = 11;

  for (int i = 0; i < steps; i++) {
    int face = rollDice();
    showNumber(face);
    delay(delays[i]);
  }

  // Final result
  int result = rollDice();
  showNumber(result);

  // Three quick LED blinks to "announce" the result
  for (int i = 0; i < 3; i++) {
    digitalWrite(PIN_LED, LOW);
    delay(80);
    digitalWrite(PIN_LED, HIGH);
    delay(80);
  }
  digitalWrite(PIN_LED, LOW);

  Serial.print("Rolled: ");
  Serial.println(result);
}

bool detectShake() {
  // Simple two-read debounce:
  //   1. See the sensor go LOW (a shake pulled the SW-420 line down).
  //   2. Wait 50 ms for the contact bouncing to settle.
  //   3. Read again. If it's still LOW, it was a real shake.
  // This is the same idea you'd use for a button. No sliding windows,
  // no edge counting - easy to read.
  if (digitalRead(PIN_SHAKE) == LOW) {
    delay(50);
    if (digitalRead(PIN_SHAKE) == LOW) {
      return true;
    }
  }
  return false;
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Shake-to-roll D6 dice booting...");

  // INPUT_PULLUP turns on the ESP32's internal pull-up resistor so the
  // pin reads HIGH when the sensor is idle. The SW-420 module usually
  // has its own pull-up too, but using INPUT_PULLUP means the sketch
  // still works on the rare board variant that doesn't.
  pinMode(PIN_SHAKE, INPUT_PULLUP);

  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);

  display.setBrightness(5);   // 0 = dim, 7 = bright
  clearDisplay();

  Serial.println("Ready. Shake the breadboard to roll.");
}

void loop() {
  unsigned long now = millis();

  if (now >= rollCooldownUntil && detectShake()) {
    Serial.println("Shake detected -> rolling");
    doRollAnimation();
    rollCooldownUntil = millis() + ROLL_COOLDOWN_MS;
  }
}

// Motion-Triggered Jump Scare Box
// ESP32 NodeMCU-32S + HC-SR501 PIR + SG90 servo + red LED.
//
// One-time setup: install the "ESP32Servo" library via
//   Arduino IDE -> Tools -> Manage Libraries... -> search "ESP32Servo"
//
// Behaviour (top to bottom, no state machine - just a linear loop):
//   1. Boot: ~60-second PIR warm-up. LED blinks fast. Motion ignored.
//   2. Armed: LED solid ON. Watching the PIR.
//   3. Motion: snap the lid open, wait 2s, ease it shut.
//   4. Cool-down: ~10 seconds before we look at the PIR again.

#include <ESP32Servo.h>

const int PIN_PIR   = 13;   // HC-SR501 OUT  -> GPIO 13 (digital input)
const int PIN_SERVO = 25;   // SG90 signal   -> GPIO 25 (quiet at boot)
const int PIN_LED   = 27;   // Red LED (via 220R) -> GPIO 27

const int SERVO_CLOSED_DEG = 0;     // lid down / spring loaded
const int SERVO_OPEN_DEG   = 120;   // lid flipped open

const unsigned long WARMUP_MS   = 60UL * 1000UL;  // PIR settle time
const unsigned long OPEN_HOLD_MS = 2000;          // how long the lid stays open
const unsigned long COOLDOWN_MS = 10UL * 1000UL;  // quiet time after a trigger

Servo lidServo;

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Jump Scare Box booting...");

  pinMode(PIN_PIR, INPUT);
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);

  lidServo.setPeriodHertz(50);              // SG90 wants 50 Hz
  lidServo.attach(PIN_SERVO, 500, 2400);    // typical SG90 pulse window
  lidServo.write(SERVO_CLOSED_DEG);

  // Warm up the PIR. Blink the LED fast so you can see we are waiting.
  Serial.println("Warming up PIR (60s)...");
  unsigned long warmStart = millis();
  while (millis() - warmStart < WARMUP_MS) {
    digitalWrite(PIN_LED, HIGH);
    delay(120);
    digitalWrite(PIN_LED, LOW);
    delay(120);
  }

  digitalWrite(PIN_LED, HIGH);              // solid LED = armed
  Serial.println("PIR ready. ARMED.");
}

void loop() {
  // Are we seeing motion?
  if (digitalRead(PIN_PIR) == HIGH) {
    Serial.println("MOTION! Flipping lid.");
    digitalWrite(PIN_LED, LOW);

    // Snap open fast - hobby servos move as fast as their gears allow.
    lidServo.write(SERVO_OPEN_DEG);
    delay(OPEN_HOLD_MS);

    // Ease shut a little more gently in case the spider is on a string.
    for (int a = SERVO_OPEN_DEG; a >= SERVO_CLOSED_DEG; a -= 5) {
      lidServo.write(a);
      delay(20);
    }
    lidServo.write(SERVO_CLOSED_DEG);

    // Cool-down: slow blink so you can see we are not armed yet.
    Serial.println("Cooling down (10s)...");
    unsigned long coolStart = millis();
    while (millis() - coolStart < COOLDOWN_MS) {
      digitalWrite(PIN_LED, HIGH);
      delay(500);
      digitalWrite(PIN_LED, LOW);
      delay(500);
    }

    digitalWrite(PIN_LED, HIGH);            // back to solid = armed
    Serial.println("Re-armed.");
  }

  delay(20);  // tiny breather so we are not hammering the PIR pin
}

// Hidden-Magnet Treasure Hunter
// ESP32 NodeMCU-32S + KY-024 (linear Hall) sensor + TM1637 4-digit display + LED
//
// Sweep the sensor near a hidden neodymium magnet. The LED blinks faster the
// closer you get, and the 4-digit display shows the live field "strength".
//
// Library required (install via Arduino IDE Library Manager):
//   "TM1637Display" by Avishay Orpaz

#include <Arduino.h>
#include <TM1637Display.h>

// ---- Pin map (must match wiring diagram) ----
const int HALL_PIN  = 34;   // ADC1_CH6, input-only on the ESP32 - perfect for analog sensors
const int LED_PIN   = 2;    // onboard blue LED + external red LED via 220R.
                            // NOTE: GPIO 2 is a strapping pin. It must be LOW (or floating)
                            // at boot. setup() writes LOW *before* pinMode OUTPUT to keep
                            // the strapping condition safe.
const int TM_CLK    = 22;
const int TM_DIO    = 21;

// ---- Tuning knobs ----
// How many samples to average when establishing the "no magnet" baseline at startup.
const int   BASELINE_SAMPLES   = 200;
// Anything below this distance-from-baseline counts as "no magnet detected".
const int   NOISE_FLOOR        = 30;
// Field strength that maps to the FASTEST blink (magnet basically touching sensor).
// You may need to lower this if your magnet is weak, or raise it if it's strong.
const int   STRENGTH_AT_MAX    = 1500;
// Blink interval bounds, in milliseconds. Far away = slow blink, close = fast blink.
const unsigned long BLINK_SLOW_MS = 800;
const unsigned long BLINK_FAST_MS = 40;

TM1637Display display(TM_CLK, TM_DIO);

int           baseline           = 2048;   // refined at startup
unsigned long lastBlinkToggle    = 0;
bool          ledOn              = false;
unsigned long lastDisplayUpdate  = 0;

void setup() {
    Serial.begin(115200);
    delay(200);
    Serial.println();
    Serial.println("Hidden-Magnet Treasure Hunter starting up.");

    // IMPORTANT: write LOW before pinMode OUTPUT so GPIO 2 (a strapping pin)
    // stays low through the moment it switches to output. Do not reorder.
    digitalWrite(LED_PIN, LOW);
    pinMode(LED_PIN, OUTPUT);

    // ESP32 ADC: 12-bit (0-4095), 11dB attenuation gives ~0-3.3V range.
    analogReadResolution(12);
    analogSetPinAttenuation(HALL_PIN, ADC_11db);

    display.setBrightness(5);   // 0 = dim, 7 = bright
    display.clear();

    // ---- Establish baseline ----
    // Hold the sensor away from any magnet for the first second of power-on.
    Serial.print("Calibrating baseline (keep magnet away)");
    long sum = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) {
        sum += analogRead(HALL_PIN);
        if (i % 25 == 0) Serial.print('.');
        delay(5);
    }
    baseline = sum / BASELINE_SAMPLES;
    Serial.println();
    Serial.print("Baseline = ");
    Serial.println(baseline);

    // Quick "ready" wink so the kid knows it's alive.
    for (int i = 0; i < 3; i++) {
        digitalWrite(LED_PIN, HIGH);
        delay(80);
        digitalWrite(LED_PIN, LOW);
        delay(80);
    }
}

// Map raw ADC reading to a 0..STRENGTH_AT_MAX "field strength" number.
// Either pole of the magnet shows up as a positive number.
int readFieldStrength() {
    int raw       = analogRead(HALL_PIN);
    int deviation = abs(raw - baseline);
    if (deviation < NOISE_FLOOR) return 0;
    return deviation;
}

// Convert field strength to a blink interval. Stronger field -> shorter interval.
unsigned long blinkIntervalFor(int strength) {
    if (strength <= 0) return 0;   // 0 means "do not blink at all"

    int clamped = strength;
    if (clamped > STRENGTH_AT_MAX) clamped = STRENGTH_AT_MAX;

    // Linear map: strength 1 -> BLINK_SLOW_MS, strength STRENGTH_AT_MAX -> BLINK_FAST_MS.
    long span     = (long)BLINK_SLOW_MS - (long)BLINK_FAST_MS;
    long interval = (long)BLINK_SLOW_MS - (span * clamped) / STRENGTH_AT_MAX;
    if (interval < (long)BLINK_FAST_MS) interval = BLINK_FAST_MS;
    return (unsigned long)interval;
}

void loop() {
    unsigned long now      = millis();
    int           strength = readFieldStrength();
    unsigned long interval = blinkIntervalFor(strength);

    // ---- Blink the LED ----
    if (interval == 0) {
        // No magnet in range -> LED off, no blinking.
        if (ledOn) {
            ledOn = false;
            digitalWrite(LED_PIN, LOW);
        }
    } else {
        if (now - lastBlinkToggle >= interval) {
            lastBlinkToggle = now;
            ledOn           = !ledOn;
            digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
        }
    }

    // ---- Update display about 10 times per second (any faster looks twitchy) ----
    if (now - lastDisplayUpdate >= 100) {
        lastDisplayUpdate = now;
        int shown = strength;
        if (shown > 9999) shown = 9999;   // 4-digit display tops out at 9999
        display.showNumberDec(shown, false);
    }

    // Small idle to keep the loop from spinning unnecessarily fast.
    delay(5);
}

// Plant SOS - XIAO ESP32-C3 + soil moisture sensor + 0.96" OLED + red LED.
//
// Reads the analog soil moisture pin and draws one of three faces on the
// OLED depending on how wet the soil is. When the soil is "thirsty" the
// red LED blinks once per second.
//
// Reliability tweaks vs. a naive version:
//   - The soil probe's VCC is driven by a GPIO (PIN_SOIL_PWR) and only
//     energised for ~10 ms around each read. Always-on 3.3 V across a
//     resistive probe electrolyses the prongs and they corrode in weeks.
//   - The OLED address is auto-detected between 0x3C and 0x3D, with the
//     result printed over Serial so you can pin it down.
//   - The polarity of the moisture reading (wet=low vs wet=high) depends
//     on the specific sensor board. Flip SENSOR_WET_IS_LOW if needed.
//
// Libraries (Arduino IDE Library Manager):
//   - Adafruit GFX Library
//   - Adafruit SSD1306
//
// Board: "XIAO_ESP32C3" under ESP32 Arduino.

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ----- Pins -----
// XIAO ESP32-C3 silkscreen D-labels map to these GPIOs:
//   D0=GPIO2 (ADC), D1=GPIO3, D2=GPIO4, D4=GPIO6 (SDA), D5=GPIO7 (SCL)
static const int PIN_SOIL      = D0;   // analog moisture input,  GPIO2
static const int PIN_LED       = D1;   // red LED + 220R,         GPIO3
static const int PIN_SOIL_PWR  = D2;   // soil sensor VCC gate,   GPIO4

// ----- OLED -----
#define OLED_W   128
#define OLED_H   64
static const uint8_t OLED_ADDR_PRIMARY = 0x3C;
static const uint8_t OLED_ADDR_FALLBACK = 0x3D;
Adafruit_SSD1306 display(OLED_W, OLED_H, &Wire, -1);

// ----- Sensor polarity -----
// Most 4-pin LM393 resistive boards: wet -> LOW number, dry -> HIGH number.
// Some capacitive replacements and a few odd resistive clones invert this.
// Watch the Serial Monitor: dunk the probe in water, then hold it in air.
// If wet gives a HIGHER number than dry, set this to false.
static const bool SENSOR_WET_IS_LOW = true;

// ----- Moisture thresholds (raw 12-bit ADC, 0..4095) -----
// These are the "wet-is-low" defaults. They are auto-flipped below if
// SENSOR_WET_IS_LOW is false, so you do not need to touch the conditionals.
// Recalibrate after watching Serial in air vs. in a glass of water.
static const int WET_BELOW = 1800;   // wetter than this -> HAPPY
static const int DRY_ABOVE = 2800;   // drier than this  -> CRYING

// LED blink state for the "thirsty" case
unsigned long lastBlinkMs = 0;
bool ledOn = false;
static const unsigned long BLINK_MS = 500;  // 500 on / 500 off = 1 Hz

enum Mood { HAPPY, SLEEPY, CRYING };

// ----- Helpers -----

// Energise the sensor, let it settle, read, then turn it off.
// Keeping the probe powered only ~10 ms per second hugely slows the
// electrolytic corrosion that eats resistive prongs in always-on use.
int readSoilRaw() {
  digitalWrite(PIN_SOIL_PWR, HIGH);
  delay(10);                          // settle time for the comparator
  int raw = analogRead(PIN_SOIL);
  digitalWrite(PIN_SOIL_PWR, LOW);
  return raw;
}

// Map a raw ADC reading to a mood, honouring SENSOR_WET_IS_LOW so the
// thresholds above stay readable regardless of probe polarity.
Mood moodFromRaw(int raw) {
  // Normalise so "small number = wet" is always true inside the compare.
  int wetness = SENSOR_WET_IS_LOW ? raw : (4095 - raw);
  if (wetness < WET_BELOW) return HAPPY;
  if (wetness < DRY_ABOVE) return SLEEPY;
  return CRYING;
}

// Try the two common SSD1306 addresses. Returns the address that worked,
// or 0 if neither responded.
uint8_t beginOLED() {
  if (display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR_PRIMARY)) {
    return OLED_ADDR_PRIMARY;
  }
  if (display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR_FALLBACK)) {
    return OLED_ADDR_FALLBACK;
  }
  return 0;
}

void drawFace(Mood mood, int rawValue) {
  display.clearDisplay();

  // Header line: raw number, so you can calibrate by watching it.
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print(F("Soil raw: "));
  display.print(rawValue);

  // Face geometry. cy is nudged up a few px from earlier drafts so the
  // frown does not crowd the mood label at the bottom of the screen.
  const int cx = OLED_W / 2;          // 64
  const int cy = 34;                  // face center Y
  const int eyeOffsetX = 16;
  const int eyeY = cy - 8;
  const int eyeR = 4;
  const int mouthR = 14;              // radius of the mouth-arc circle

  // Eyes are the same for all moods.
  display.fillCircle(cx - eyeOffsetX, eyeY, eyeR, SSD1306_WHITE);
  display.fillCircle(cx + eyeOffsetX, eyeY, eyeR, SSD1306_WHITE);

  // Mouth + label change per mood. Mouths are real circle-arc primitives
  // (Adafruit_GFX drawCircleHelper), not point-by-point parabolas, so the
  // prose and the code agree on "arc, line, arc".
  //   corner bits: 1=top-right, 2=bottom-right, 4=bottom-left, 8=top-left
  display.setCursor(0, OLED_H - 8);
  switch (mood) {
    case HAPPY: {
      display.print(F("HAPPY :)"));
      // Smile: bottom half of a circle (corners 4 + 2).
      display.drawCircleHelper(cx, cy + 2, mouthR, 4 | 2, SSD1306_WHITE);
      break;
    }
    case SLEEPY: {
      display.print(F("Sleepy..."));
      // Straight-line mouth.
      display.drawFastHLine(cx - mouthR, cy + 8, mouthR * 2, SSD1306_WHITE);
      break;
    }
    case CRYING: {
      display.print(F("THIRSTY!"));
      // Frown: top half of a circle drawn lower down (corners 1 + 8).
      display.drawCircleHelper(cx, cy + 14, mouthR, 1 | 8, SSD1306_WHITE);
      // Two tear drops under each eye.
      display.fillCircle(cx - eyeOffsetX, eyeY + 10, 2, SSD1306_WHITE);
      display.fillCircle(cx + eyeOffsetX, eyeY + 10, 2, SSD1306_WHITE);
      break;
    }
  }

  display.display();
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println(F("Plant SOS booting..."));

  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);

  pinMode(PIN_SOIL_PWR, OUTPUT);
  digitalWrite(PIN_SOIL_PWR, LOW);     // sensor off until we read

  // ADC on ESP32-C3 is 12-bit by default; make it explicit.
  analogReadResolution(12);

  // I2C uses XIAO defaults: SDA=GPIO6 (D4), SCL=GPIO7 (D5).
  Wire.begin();

  uint8_t addr = beginOLED();
  if (addr == 0) {
    Serial.println(F("OLED not found at 0x3C or 0x3D - check wiring."));
    // Blink the LED forever to signal the failure.
    while (true) {
      digitalWrite(PIN_LED, HIGH);
      delay(150);
      digitalWrite(PIN_LED, LOW);
      delay(150);
    }
  }
  Serial.print(F("OLED OK at 0x"));
  Serial.println(addr, HEX);

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println(F("Plant SOS"));
  display.println(F("warming up..."));
  display.display();
  delay(800);
}

void loop() {
  int raw = readSoilRaw();
  Serial.print(F("soil raw="));
  Serial.println(raw);

  Mood mood = moodFromRaw(raw);
  drawFace(mood, raw);

  // LED behaviour: only the thirsty mood blinks. Otherwise off.
  if (mood == CRYING) {
    unsigned long now = millis();
    if (now - lastBlinkMs >= BLINK_MS) {
      lastBlinkMs = now;
      ledOn = !ledOn;
      digitalWrite(PIN_LED, ledOn ? HIGH : LOW);
    }
  } else {
    if (ledOn) {
      ledOn = false;
      digitalWrite(PIN_LED, LOW);
    }
  }

  // Sample about twice a second - plants are slow, we do not need fast loops.
  delay(500);
}

/*
 * Simon Says - 4-color memory game
 * Target board: ESP32 NodeMCU-32S
 *
 * How it plays:
 *   - The board flashes a growing sequence of colors (red, yellow, green, blue).
 *   - You press the matching buttons in the same order.
 *   - Get it right and the sequence grows by one and speeds up a little.
 *   - Get it wrong and all four LEDs blink three times to tell you the game is over.
 *   - Then it restarts with a new random sequence.
 */

#include <Arduino.h>

// ---- Pin assignments (match the wiring diagram) ----
// LEDs: any output-capable GPIO is fine. We avoid 0, 2, 12, 15 (boot pins)
// and 2 specifically because it is the on-board user LED on this board.
const int LED_PINS[4] = {25, 26, 27, 14};       // Red, Yellow, Green, Blue

// Buttons: ALL four pins MUST have internal pull-ups so INPUT_PULLUP works.
// GPIO 34, 35, 36, 39 are input-only and have NO internal pull-up - do not
// use them here without an external 10k pull-up to 3V3.
// 32 and 33 are general-purpose; 13 and 19 are also safe and pull-up capable.
const int BTN_PINS[4] = {32, 33, 13, 19};       // Red, Yellow, Green, Blue

const char* COLOR_NAMES[4] = {"RED", "YELLOW", "GREEN", "BLUE"};

// ---- Game tuning ----
const int  MAX_SEQUENCE   = 64;     // longest sequence we will ever remember
const int  START_FLASH_MS = 600;    // how long each LED stays on at round 1
const int  MIN_FLASH_MS   = 150;    // we never go faster than this
const int  GAP_MS         = 200;    // pause between LEDs in the playback
const unsigned long PLAYER_TIMEOUT_MS = 5000; // 5 s to press the next button
const int  DEBOUNCE_MS    = 25;     // tactile button bounce window

// ---- Game state ----
int sequence[MAX_SEQUENCE];
int sequenceLength = 0;
int flashDuration  = START_FLASH_MS;

// ---------- helpers ----------

void allLedsOff() {
  for (int i = 0; i < 4; i++) digitalWrite(LED_PINS[i], LOW);
}

void flashColor(int colorIndex, int durationMs) {
  digitalWrite(LED_PINS[colorIndex], HIGH);
  delay(durationMs);
  digitalWrite(LED_PINS[colorIndex], LOW);
  delay(GAP_MS);
}

// Read one button with a tiny debounce. Returns true if pressed.
// INPUT_PULLUP means "not pressed = HIGH, pressed = LOW".
bool isPressed(int colorIndex) {
  if (digitalRead(BTN_PINS[colorIndex]) == LOW) {
    delay(DEBOUNCE_MS);
    if (digitalRead(BTN_PINS[colorIndex]) == LOW) {
      return true;
    }
  }
  return false;
}

// Block until ANY button is pressed, or timeout expires.
// Returns the color index pressed, or -1 on timeout.
int waitForButton(unsigned long timeoutMs) {
  unsigned long start = millis();
  while (millis() - start < timeoutMs) {
    for (int i = 0; i < 4; i++) {
      if (isPressed(i)) {
        // Light the LED while the button is held so it feels responsive.
        digitalWrite(LED_PINS[i], HIGH);
        // Wait for release so we don't register one press as many.
        while (digitalRead(BTN_PINS[i]) == LOW) {
          delay(5);
        }
        delay(DEBOUNCE_MS);
        digitalWrite(LED_PINS[i], LOW);
        return i;
      }
    }
    delay(5);
  }
  return -1;
}

void playSequence() {
  for (int i = 0; i < sequenceLength; i++) {
    flashColor(sequence[i], flashDuration);
  }
}

void gameOverAnimation() {
  Serial.println("Game over!");
  for (int blink = 0; blink < 3; blink++) {
    for (int i = 0; i < 4; i++) digitalWrite(LED_PINS[i], HIGH);
    delay(300);
    allLedsOff();
    delay(300);
  }
  delay(800);
}

void winRoundAnimation() {
  // Quick chase to celebrate a successful round.
  for (int i = 0; i < 4; i++) {
    digitalWrite(LED_PINS[i], HIGH);
    delay(60);
    digitalWrite(LED_PINS[i], LOW);
  }
  delay(400);
}

void resetGame() {
  sequenceLength = 0;
  flashDuration  = START_FLASH_MS;
}

// ---------- Arduino entry points ----------

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Simon Says - 4-color memory game");

  for (int i = 0; i < 4; i++) {
    pinMode(LED_PINS[i], OUTPUT);
    digitalWrite(LED_PINS[i], LOW);
    // INPUT_PULLUP works on all four chosen button pins (32, 33, 13, 19).
    pinMode(BTN_PINS[i], INPUT_PULLUP);
  }

  // Seed the randomizer with electrical noise on an unused analog pin.
  // GPIO 36 (SENSOR_VP) is input-only and floating here, so the reading
  // is essentially noise. If you ever wire something to GPIO 36 the seed
  // will become more deterministic - swap to another unused ADC pin.
  randomSeed(analogRead(36));

  // Friendly boot animation so you know the board is alive.
  for (int i = 0; i < 4; i++) flashColor(i, 150);
}

void loop() {
  // Add one new random step to the sequence.
  if (sequenceLength < MAX_SEQUENCE) {
    sequence[sequenceLength] = random(0, 4);
    sequenceLength++;
  }

  Serial.print("Round ");
  Serial.print(sequenceLength);
  Serial.print(" - new color: ");
  Serial.println(COLOR_NAMES[sequence[sequenceLength - 1]]);

  delay(500);
  playSequence();

  // Now the player has to repeat the whole sequence.
  for (int step = 0; step < sequenceLength; step++) {
    int pressed = waitForButton(PLAYER_TIMEOUT_MS);
    if (pressed == -1) {
      Serial.println("Timed out waiting for input.");
      gameOverAnimation();
      resetGame();
      return;
    }
    if (pressed != sequence[step]) {
      Serial.print("Wrong! Expected ");
      Serial.print(COLOR_NAMES[sequence[step]]);
      Serial.print(" but got ");
      Serial.println(COLOR_NAMES[pressed]);
      gameOverAnimation();
      resetGame();
      return;
    }
  }

  // Survived the round - speed things up a touch.
  winRoundAnimation();
  flashDuration = max(MIN_FLASH_MS, flashDuration - 40);
}

/*
 * Stopwatch + Lap Memory on Serial Monitor
 *
 * Hardware: ONE ESP32 NodeMCU-32S, USB cable. Nothing else.
 *
 *   - BOOT button (GPIO 0, active-LOW) is the only user input.
 *   - Built-in blue LED (GPIO 2) blinks once per second while running,
 *     and is off when stopped. Visual "is it running?" indicator.
 *   - Serial Monitor at 115200 baud is the display.
 *
 * Controls:
 *   - Short tap of BOOT (< 600 ms):  toggle start / stop.
 *   - Long press of BOOT (>= 600 ms, while running):  record a lap.
 *   - Long press of BOOT (>= 600 ms, while stopped):  reset to zero.
 *
 * The Serial Monitor prints the running MM:SS once a second, and prints
 * each recorded lap in MM:SS.hh (hundredths of a second) along with the
 * split since the previous lap. The fastest lap so far is tagged "BEST".
 *
 * Notes for the reader:
 *   - We deliberately do NOT use delay(). Every timing decision is made
 *     by comparing millis() values, so the loop stays responsive.
 *   - The BOOT button is wired with a hardware pull-up on the board, so
 *     INPUT_PULLUP is requested for safety but is not strictly required.
 *   - At power-on the BOOT button may already be held by the user (for
 *     flash mode). We sample its stable state once in setup() and treat
 *     that as the baseline, so we do not fire a phantom "release" event
 *     when the user lets go just after boot.
 */

#include <Arduino.h>

// ---------- pin map (matches the wiring diagram) ----------
const uint8_t PIN_BTN = 0;   // BOOT button, active-LOW
const uint8_t PIN_LED = 2;   // built-in blue LED (try 5 or 22 if your clone differs)

// ---------- timing constants ----------
const uint16_t DEBOUNCE_MS    = 25;
const uint16_t LONG_PRESS_MS  = 600;
const uint16_t PRINT_PERIOD_MS = 1000;  // how often we reprint MM:SS while running
const uint16_t LED_BLINK_MS    = 500;   // LED toggles every 500 ms -> 1 Hz blink

// ---------- stopwatch state ----------
bool      running       = false;
uint32_t  startMillis   = 0;   // millis() value at the moment we last started
uint32_t  accumulatedMs = 0;   // total time banked from previous start/stop cycles

// ---------- lap memory ----------
const uint8_t MAX_LAPS = 20;
uint32_t laps[MAX_LAPS];       // each entry = total elapsed ms at the moment Lap was pressed
uint8_t  lapCount     = 0;
uint8_t  bestLapIndex = 0xFF;  // 0xFF means "no best yet"
uint32_t bestLapMs    = 0xFFFFFFFF;

// ---------- button debounce + short/long detection ----------
// Event codes returned by readButton().
const uint8_t EVT_NONE  = 0;
const uint8_t EVT_SHORT = 1;
const uint8_t EVT_LONG  = 2;

struct Button {
    uint8_t  pin;
    bool     lastStable;     // last debounced level. HIGH = not pressed (pull-up).
    bool     lastReading;    // last raw level we saw on the pin
    uint32_t lastChangeMs;   // when the raw level last changed
    uint32_t pressedAtMs;    // when the most recent press started (used for long-press)
    bool     longFired;      // have we already reported a LONG event for this press?
};

Button btn = { PIN_BTN, true, true, 0, 0, false };

// Reads the button and reports an event:
//   EVT_NONE  - nothing changed
//   EVT_SHORT - button was just released after a tap (< LONG_PRESS_MS)
//   EVT_LONG  - button has been held LONG_PRESS_MS while still down (fires once)
uint8_t readButton(Button &b) {
    uint8_t  event = EVT_NONE;
    bool     reading = digitalRead(b.pin);
    uint32_t now = millis();

    // raw-level change -> restart the debounce window
    if (reading != b.lastReading) {
        b.lastChangeMs = now;
        b.lastReading  = reading;
    }

    // debounce window elapsed AND the stable level changed -> commit it
    if ((now - b.lastChangeMs) > DEBOUNCE_MS && reading != b.lastStable) {
        b.lastStable = reading;
        if (b.lastStable == LOW) {
            // press just started
            b.pressedAtMs = now;
            b.longFired   = false;
        } else {
            // press just ended - if we have not already fired the long event,
            // and the press was short, report a short tap
            if (!b.longFired) {
                event = EVT_SHORT;
            }
        }
    }

    // while the button is being held, fire EVT_LONG exactly once at the threshold
    if (b.lastStable == LOW && !b.longFired && (now - b.pressedAtMs) >= LONG_PRESS_MS) {
        b.longFired = true;
        event = EVT_LONG;
    }

    return event;
}

// ---------- helpers ----------
uint32_t currentElapsedMs() {
    if (running) {
        return accumulatedMs + (millis() - startMillis);
    }
    return accumulatedMs;
}

void formatMmSs(uint32_t ms, char *out, size_t outSize) {
    uint16_t mm = (ms / 60000) % 100;
    uint16_t ss = (ms / 1000)  % 60;
    snprintf(out, outSize, "%02u:%02u", mm, ss);
}

void formatMmSsHh(uint32_t ms, char *out, size_t outSize) {
    uint16_t mm = (ms / 60000) % 100;
    uint16_t ss = (ms / 1000)  % 60;
    uint16_t hh = (ms % 1000)  / 10;   // hundredths
    snprintf(out, outSize, "%02u:%02u.%02u", mm, ss, hh);
}

void printRunningTime() {
    char buf[8];
    formatMmSs(currentElapsedMs(), buf, sizeof(buf));
    Serial.print(F("[RUN] "));
    Serial.println(buf);
}

void recordLap() {
    if (!running) return;
    if (lapCount >= MAX_LAPS) {
        Serial.println(F("[LAP] memory full - ignoring (raise MAX_LAPS)"));
        return;
    }

    uint32_t now     = currentElapsedMs();
    uint32_t splitMs = (lapCount == 0) ? now : (now - laps[lapCount - 1]);
    laps[lapCount]   = now;

    if (splitMs < bestLapMs) {
        bestLapMs    = splitMs;
        bestLapIndex = lapCount;
    }

    char totalBuf[12];
    char splitBuf[12];
    formatMmSsHh(now,     totalBuf, sizeof(totalBuf));
    formatMmSsHh(splitMs, splitBuf, sizeof(splitBuf));

    Serial.print(F("[LAP "));
    if (lapCount + 1 < 10) Serial.print(' ');
    Serial.print(lapCount + 1);
    Serial.print(F("] total "));
    Serial.print(totalBuf);
    Serial.print(F("  split "));
    Serial.print(splitBuf);
    if (lapCount == bestLapIndex) {
        Serial.print(F("  <-- BEST"));
    }
    Serial.println();

    lapCount++;
}

void resetAll() {
    running       = false;
    accumulatedMs = 0;
    lapCount      = 0;
    bestLapIndex  = 0xFF;
    bestLapMs     = 0xFFFFFFFF;
    digitalWrite(PIN_LED, LOW);
    Serial.println(F("[RESET] cleared"));
}

void printHelp() {
    Serial.println(F("------------------------------------------------------------"));
    Serial.println(F("Stopwatch + Lap Memory"));
    Serial.println(F("  short tap BOOT  : start / stop"));
    Serial.println(F("  long hold BOOT  : record a lap (running) or reset (stopped)"));
    Serial.println(F("  built-in LED    : blinks once per second while running"));
    Serial.println(F("------------------------------------------------------------"));
}

// ---------- Arduino entry points ----------
void setup() {
    Serial.begin(115200);
    delay(50);

    pinMode(PIN_BTN, INPUT_PULLUP);
    pinMode(PIN_LED, OUTPUT);
    digitalWrite(PIN_LED, LOW);

    // Sample the button's stable level once so we do not fire a phantom
    // event if the user is still holding BOOT just after boot.
    bool boot = digitalRead(PIN_BTN);
    btn.lastReading = boot;
    btn.lastStable  = boot;
    btn.lastChangeMs = millis();

    printHelp();
}

void loop() {
    // --- 1. user input ---
    uint8_t evt = readButton(btn);
    if (evt == EVT_SHORT) {
        if (running) {
            // stop: bank the elapsed time so the next start resumes from it
            accumulatedMs += (millis() - startMillis);
            running = false;
            digitalWrite(PIN_LED, LOW);
            char buf[8];
            formatMmSs(accumulatedMs, buf, sizeof(buf));
            Serial.print(F("[STOP] at "));
            Serial.println(buf);
        } else {
            // start (or resume)
            startMillis = millis();
            running     = true;
            Serial.println(F("[START]"));
        }
    } else if (evt == EVT_LONG) {
        if (running) {
            recordLap();
        } else {
            resetAll();
        }
    }

    // --- 2. LED heartbeat (blink at 1 Hz only while running) ---
    static uint32_t lastLedToggleMs = 0;
    static bool ledState = false;
    uint32_t now = millis();
    if (running && (now - lastLedToggleMs) >= LED_BLINK_MS) {
        lastLedToggleMs = now;
        ledState = !ledState;
        digitalWrite(PIN_LED, ledState ? HIGH : LOW);
    }

    // --- 3. Serial Monitor refresh (once a second while running) ---
    static uint32_t lastPrintMs = 0;
    if (running && (now - lastPrintMs) >= PRINT_PERIOD_MS) {
        lastPrintMs = now;
        printRunningTime();
    }
}

#include <WiFi.h>
#include <WebServer.h>

// ---- WiFi credentials ----
const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASS = "PASSWORD_HERE";

// ---- Pins ----
// Button between GPIO 4 and GND. We enable the internal pull-up, so the
// pin reads HIGH when the button is open and LOW when it is pressed.
const int BUTTON_PIN = 4;
// Built-in blue LED on the NodeMCU-32S. Lights briefly each time the
// doorbell fires so we can see the press without watching the browser.
const int LED_PIN = 2;

// ---- State ----
WebServer server(80);

// "ring count" goes up by one every time the button is pressed.
// The web page polls /status and notices when this number has changed,
// then plays its "Ding!" animation. Using a counter (not just a flag)
// means we never miss a press if two come close together.
volatile unsigned long ringCount = 0;
unsigned long lastRingMillis = 0;

// Debounce: ignore another press within 400 ms of the previous one,
// otherwise the mechanical button's contact bounce registers as several
// rings for one push.
const unsigned long DEBOUNCE_MS = 400;
int lastButtonReading = HIGH;

// ---- Web page ----
// Served at "/". Plain HTML + a tiny bit of JavaScript that polls the
// ESP32 once a second for the current ring count. When the count goes
// up, the page shows the "Ding!" message and the time it happened.
const char INDEX_HTML[] PROGMEM = R"HTML(
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Family Doorbell</title>
  <style>
    body { font-family: system-ui, sans-serif; text-align: center;
           background: #0f172a; color: #e2e8f0; margin: 0; padding: 2rem; }
    h1 { font-size: 2rem; margin-top: 3rem; }
    #status { font-size: 3rem; margin-top: 2rem; transition: color .3s; }
    #stamp  { font-size: 1.25rem; color: #94a3b8; margin-top: 1rem; }
    .ring   { color: #f59e0b; animation: pulse 1s ease-out 3; }
    @keyframes pulse {
      0%   { transform: scale(1);   }
      50%  { transform: scale(1.15);}
      100% { transform: scale(1);   }
    }
  </style>
</head>
<body>
  <h1>Family Doorbell</h1>
  <div id="status">All quiet.</div>
  <div id="stamp"></div>
  <script>
    let lastCount = 0;
    let firstLoad = true;
    async function poll() {
      try {
        const r = await fetch('/status');
        const j = await r.json();
        if (firstLoad) {
          lastCount = j.count;
          firstLoad = false;
        } else if (j.count > lastCount) {
          lastCount = j.count;
          const s = document.getElementById('status');
          s.textContent = "Ding! Someone's at the door";
          s.className = 'ring';
          const stamp = new Date();
          document.getElementById('stamp').textContent =
            'Rung at ' + stamp.toLocaleTimeString();
          setTimeout(() => {
            s.textContent = 'All quiet.';
            s.className = '';
          }, 8000);
        }
      } catch (e) { /* ignore - just try again next tick */ }
    }
    setInterval(poll, 1000);
    poll();
  </script>
</body>
</html>
)HTML";

void handleRoot() {
  server.send_P(200, "text/html", INDEX_HTML);
}

void handleStatus() {
  // Tiny JSON the page can poll. Including millis() lets the page
  // tell when the ESP32 itself was last alive, useful for debugging.
  String body = "{\"count\":";
  body += ringCount;
  body += ",\"uptime_ms\":";
  body += millis();
  body += "}";
  server.send(200, "application/json", body);
}

void handleNotFound() {
  server.send(404, "text/plain", "Not found");
}

void setup() {
  Serial.begin(115200);
  delay(200);

  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  Serial.print("Connecting to ");
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);

  // Blink the LED slowly while we wait for the WiFi to come up so we
  // can tell at a glance whether the board is stuck in "connecting".
  while (WiFi.status() != WL_CONNECTED) {
    digitalWrite(LED_PIN, HIGH);
    delay(250);
    digitalWrite(LED_PIN, LOW);
    delay(250);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Connected. Open this in a browser: http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/status", handleStatus);
  server.onNotFound(handleNotFound);
  server.begin();
}

void loop() {
  server.handleClient();

  int reading = digitalRead(BUTTON_PIN);
  unsigned long now = millis();

  // Detect a fresh press: previous reading HIGH, current reading LOW,
  // and at least DEBOUNCE_MS since the last accepted press.
  if (lastButtonReading == HIGH && reading == LOW &&
      (now - lastRingMillis) > DEBOUNCE_MS) {
    ringCount++;
    lastRingMillis = now;
    Serial.print("Ding! Ring count is now ");
    Serial.println(ringCount);

    // Flash the onboard LED so the press is visible even without a phone.
    digitalWrite(LED_PIN, HIGH);
    delay(120);
    digitalWrite(LED_PIN, LOW);
  }
  lastButtonReading = reading;
}

// WiFi Signal Strength Meter on OLED
// Board:  ESP32 NodeMCU-32S
// Screen: SSD1306 128x64 OLED, I2C, address 0x3C
// Wiring: SDA -> GPIO 21, SCL -> GPIO 22, VCC -> 3V3, GND -> GND
//
// Install these libraries via Arduino IDE Library Manager once:
//   - "Adafruit SSD1306"  by Adafruit
//   - "Adafruit GFX Library" by Adafruit
//
// Before uploading: replace PASSWORD_HERE below with the real GeeFam
// WiFi password. Credentials live inside this sketch, not in CLAUDE.md.
//
// What it does: connects to WiFi, then every 250 ms reads the current
// RSSI (signal strength) and draws a bar graph + numeric value + a
// plain-English quality label. Walk around the house holding the
// ESP32 + power bank to hunt for weak spots.

#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ---- WiFi credentials ----
const char* WIFI_SSID     = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";

// ---- I2C pins (ESP32 defaults) ----
const int PIN_SDA = 21;
const int PIN_SCL = 22;

// ---- OLED config ----
const int SCREEN_WIDTH  = 128;
const int SCREEN_HEIGHT = 64;
const int OLED_RESET    = -1;     // share the ESP32 reset
const int OLED_ADDR     = 0x3C;   // standard for these modules

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// RSSI range we map onto the bar. -30 dBm = "on top of the router",
// -90 dBm = "barely audible".
const int RSSI_STRONG = -30;
const int RSSI_WEAK   = -90;

void connectWiFi() {
  display.clearDisplay();
  display.setCursor(0, 0);
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.println("Connecting to:");
  display.println(WIFI_SSID);
  display.display();

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 20000) {
    delay(250);
    display.print(".");
    display.display();
  }

  display.clearDisplay();
  display.setCursor(0, 0);
  if (WiFi.status() == WL_CONNECTED) {
    display.println("Connected!");
    display.print("IP: ");
    display.println(WiFi.localIP());
  } else {
    display.println("WiFi failed.");
    display.println("Will retry...");
  }
  display.display();
  delay(1500);
}

const char* qualityLabel(int rssi) {
  if (rssi >= -55) return "Excellent";
  if (rssi >= -67) return "Good";
  if (rssi >= -75) return "Okay";
  if (rssi >= -85) return "Weak";
  return "Dead zone";
}

void drawMeter(int rssi) {
  display.clearDisplay();

  // Header: SSID
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("SSID: ");
  display.println(WIFI_SSID);

  // Big RSSI number
  display.setTextSize(2);
  display.setCursor(0, 14);
  display.print(rssi);
  display.print(" dBm");

  // Quality label
  display.setTextSize(1);
  display.setCursor(0, 36);
  display.print("Signal: ");
  display.println(qualityLabel(rssi));

  // Bar graph along the bottom
  int barX = 0;
  int barY = 50;
  int barW = SCREEN_WIDTH - 1;
  int barH = 12;

  // Outline
  display.drawRect(barX, barY, barW, barH, SSD1306_WHITE);

  // Fill width mapped from RSSI range to bar width
  int clamped = rssi;
  if (clamped > RSSI_STRONG) clamped = RSSI_STRONG;
  if (clamped < RSSI_WEAK)   clamped = RSSI_WEAK;
  int fillW = map(clamped, RSSI_WEAK, RSSI_STRONG, 0, barW - 2);
  if (fillW > 0) {
    display.fillRect(barX + 1, barY + 1, fillW, barH - 2, SSD1306_WHITE);
  }

  display.display();
}

void drawDisconnected() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("WiFi lost.");
  display.println("Reconnecting...");
  display.display();
}

void setup() {
  Serial.begin(115200);
  delay(200);

  Wire.begin(PIN_SDA, PIN_SCL);

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("SSD1306 init failed - check wiring and address (0x3C).");
    while (true) {
      delay(1000);
    }
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("WiFi RSSI Meter");
  display.println("starting...");
  display.display();
  delay(800);

  connectWiFi();
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    drawDisconnected();
    WiFi.reconnect();
    delay(1000);
    return;
  }

  int rssi = WiFi.RSSI();
  Serial.print("RSSI: ");
  Serial.print(rssi);
  Serial.println(" dBm");

  drawMeter(rssi);
  delay(250);
}

// Distance-Triggered Treat Dispenser
// ESP32 NodeMCU + HC-SR04 + SG90 servo + TM1637 4-digit display
//
// Hold your hand ~10 cm above the ultrasonic sensor; the servo rotates
// the slotted disk once and the running count on the display goes up.
//
// Libraries to install via Arduino IDE > Library Manager:
//   - "ESP32Servo" by Kevin Harrington / John K. Bennett
//   - "TM1637Display" by Avishay Orpaz

#include <Arduino.h>
#include <ESP32Servo.h>
#include <TM1637Display.h>

// ---- Pin assignments (must match the Mermaid wiring diagram) ----
const int PIN_TRIG    = 5;   // HC-SR04 TRIG (ESP32 3.3V out is fine for the input)
const int PIN_ECHO    = 18;  // HC-SR04 ECHO via 1k/2k divider down to ~3.3V
const int PIN_SERVO   = 13;  // SG90 signal wire (orange/yellow)
const int PIN_TM_CLK  = 22;  // TM1637 CLK
const int PIN_TM_DIO  = 21;  // TM1637 DIO

// ---- Behaviour tuning ----
const float TRIGGER_CM        = 10.0;   // hand must be within this distance
const float TRIGGER_HYST_CM   = 20.0;   // must move back beyond this to re-arm
const int   SERVO_REST_ANGLE  = 0;      // disk slot blocked
const int   SERVO_DISPENSE    = 90;     // disk rotated to drop one M&M
const unsigned long DISPENSE_HOLD_MS = 350;  // hold open, then hold closed
const unsigned long LOOP_MS          = 60;   // ~16 Hz sensor polling when idle

Servo treatServo;
TM1637Display display(PIN_TM_CLK, PIN_TM_DIO);

int  treatCount = 0;
bool armed      = true;   // false while hand still hovering, prevents repeats

// Non-blocking dispense state machine. The servo move is launched from loop()
// so that ultrasonic polling does not pause for ~700 ms during a dispense.
enum DispenseState { IDLE, OPENING, CLOSING };
DispenseState dispenseState = IDLE;
unsigned long dispenseStateStartedMs = 0;

// Measure distance in centimetres. Returns -1.0 on timeout.
float readDistanceCm() {
  digitalWrite(PIN_TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);

  // 25 ms timeout corresponds to a round-trip of ~430 cm, i.e. a maximum
  // measurable one-way distance of ~4 m. Plenty for hand-over-dispenser use.
  unsigned long pulseUs = pulseIn(PIN_ECHO, HIGH, 25000UL);
  if (pulseUs == 0) return -1.0;

  // Speed of sound ~343 m/s -> 0.0343 cm/us, divide by 2 for round trip.
  return (pulseUs * 0.0343f) / 2.0f;
}

void startDispense() {
  treatServo.write(SERVO_DISPENSE);
  dispenseState = OPENING;
  dispenseStateStartedMs = millis();
}

void serviceDispense() {
  if (dispenseState == IDLE) return;

  unsigned long elapsed = millis() - dispenseStateStartedMs;

  if (dispenseState == OPENING && elapsed >= DISPENSE_HOLD_MS) {
    treatServo.write(SERVO_REST_ANGLE);
    dispenseState = CLOSING;
    dispenseStateStartedMs = millis();
  } else if (dispenseState == CLOSING && elapsed >= DISPENSE_HOLD_MS) {
    treatCount++;
    display.showNumberDec(treatCount, false);
    Serial.print("Dispensed. Total = ");
    Serial.println(treatCount);
    dispenseState = IDLE;
  }
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println("Treat dispenser starting...");

  pinMode(PIN_TRIG, OUTPUT);
  pinMode(PIN_ECHO, INPUT);
  digitalWrite(PIN_TRIG, LOW);

  treatServo.setPeriodHertz(50);                // standard 50 Hz servo PWM
  treatServo.attach(PIN_SERVO, 500, 2400);      // SG90 typical pulse range
  treatServo.write(SERVO_REST_ANGLE);

  // TM1637Display brightness: argument is 0..7 (dim..bright). The library
  // ORs in the 0x08 "display on" bit internally, so just pass 7 for max.
  display.setBrightness(7);
  display.showNumberDec(treatCount, false);

  Serial.println("Ready. Hold your hand ~10 cm above the sensor.");
}

void loop() {
  // Poll the sensor every loop, even mid-dispense, so the ~16 Hz claim holds.
  float d = readDistanceCm();

  if (d > 0.0f) {
    // Trigger on a clean "hand present" event, then disarm until the
    // hand goes away, so one wave = one M&M (not a stream).
    if (armed && d <= TRIGGER_CM && dispenseState == IDLE) {
      armed = false;
      startDispense();
    } else if (!armed && d >= TRIGGER_HYST_CM) {
      armed = true;
    }
  }

  serviceDispense();

  delay(LOOP_MS);
}

#include <WiFi.h>
#include <HTTPClient.h>
#include <esp_sleep.h>
#include <driver/gpio.h>

// WiFi credentials
const char* WIFI_SSID = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";

// Pins
const gpio_num_t TILT_PIN = GPIO_NUM_2;  // D0 on the XIAO - tilt switch input (wake source)
const int LED_PIN  = 3;                  // D1 on the XIAO - blue LED indicator

// How long to keep the LED on as a visible "mail!" pulse (ms)
const unsigned long LED_ON_MS = 5000;

// How long to wait for WiFi before giving up (ms)
const unsigned long WIFI_TIMEOUT_MS = 15000;

// After we wake, ignore further wiggles for this long, to ride out a bouncing tilt switch.
const unsigned long DEBOUNCE_HOLDOFF_MS = 3000;

// Counter that survives deep sleep
RTC_DATA_ATTR int bootCount = 0;

void flashLed(int times, int onMs, int offMs) {
  for (int i = 0; i < times; i++) {
    digitalWrite(LED_PIN, HIGH);
    delay(onMs);
    digitalWrite(LED_PIN, LOW);
    delay(offMs);
  }
}

bool connectWifi() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED) {
    if (millis() - start > WIFI_TIMEOUT_MS) {
      return false;
    }
    delay(250);
  }
  return true;
}

void sendPing() {
  // Simple GET to a public test endpoint. Swap for your own webhook /
  // Home Assistant URL once the Pi is online (see Things to change).
  HTTPClient http;
  String url = "http://worldtimeapi.org/api/timezone/Etc/UTC";
  http.begin(url);
  http.setTimeout(5000);
  int code = http.GET();
  http.end();

  if (code > 0) {
    // Two quick flashes = "ping sent OK"
    flashLed(2, 100, 100);
  } else {
    // One long flash = "ping failed but I woke up"
    flashLed(1, 800, 0);
  }
}

void goToSleep() {
  // Make sure LED is off before sleeping
  digitalWrite(LED_PIN, LOW);

  // ESP32-C3 deep-sleep wake-on-GPIO.
  //   - The classic ESP32's ext1 API does NOT work on the C3 (no RTC_IO peripheral).
  //   - gpio_wakeup_enable() sets the trigger level for the pin.
  //   - esp_deep_sleep_enable_gpio_wakeup() arms wake-from-deep-sleep on the bitmask.
  // We use HIGH-level wake because our external 100k pull-down keeps the pin LOW
  // while the flap is closed; the tilt switch pulls it up to 3V3 when it flips.
  gpio_wakeup_enable(TILT_PIN, GPIO_INTR_HIGH_LEVEL);
  esp_deep_sleep_enable_gpio_wakeup(1ULL << TILT_PIN, ESP_GPIO_WAKEUP_GPIO_HIGH);

  // Bye!
  esp_deep_sleep_start();
}

void setup() {
  Serial.begin(115200);
  delay(200);  // brief wait so Serial is ready

  bootCount++;
  Serial.print("Wake #");
  Serial.println(bootCount);

  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  // Plain digital input. The pin is held LOW by the external 100k pull-down
  // to GND on the breadboard; the tilt switch + 100nF cap form an RC debounce
  // filter that rides out contact bounce.
  // (We deliberately do NOT use INPUT_PULLDOWN: the C3's internal pull-downs
  // are in the digital domain and are powered off during deep sleep, so they
  // can't hold the line during the part of the cycle that matters most.)
  pinMode(TILT_PIN, INPUT);

  // Visible "I woke up!" pulse so a human can see something happened
  // even if WiFi is down.
  digitalWrite(LED_PIN, HIGH);

  esp_sleep_wakeup_cause_t reason = esp_sleep_get_wakeup_cause();
  if (reason == ESP_SLEEP_WAKEUP_GPIO) {
    Serial.println("Woke from tilt switch - mailbox opened!");
  } else {
    Serial.println("First boot / reset");
  }

  if (connectWifi()) {
    Serial.print("WiFi OK, IP=");
    Serial.println(WiFi.localIP());
    sendPing();
  } else {
    Serial.println("WiFi failed - skipping ping");
    // Three medium flashes = "no WiFi"
    flashLed(3, 300, 300);
  }

  // Keep the LED on a bit longer so it's obvious from across the room
  digitalWrite(LED_PIN, HIGH);
  delay(LED_ON_MS);

  // Software debounce hold-off: spin here long enough that the tilt switch
  // has stopped wiggling. If it's still HIGH at the end of the hold-off
  // (mail carrier is still rummaging) we just sleep anyway - the next wake
  // happens on the next rising edge after the line falls and rises again.
  unsigned long holdoffStart = millis();
  while (millis() - holdoffStart < DEBOUNCE_HOLDOFF_MS) {
    delay(50);
  }

  WiFi.disconnect(true);
  WiFi.mode(WIFI_OFF);

  Serial.println("Sleeping until next mailbox event...");
  Serial.flush();
  goToSleep();
}

void loop() {
  // Never reached - setup() always ends in deep sleep.
}

/*
 * OLED Spirit Level
 *
 * Board: XIAO ESP32-C3 (3.3 V logic)
 * I2C bus shared by:
 *   - MPU-6500 IMU       at address 0x68
 *   - SSD1306 OLED 128x64 at address 0x3C
 *
 * Wiring (matches the diagram):
 *   XIAO 3V3 -> IMU VCC, OLED VCC
 *   XIAO GND -> IMU GND, OLED GND, LED cathode
 *   XIAO D4 (GPIO6) SDA -> IMU SDA + OLED SDA
 *   XIAO D5 (GPIO7) SCL -> IMU SCL + OLED SCL
 *   XIAO D2 (GPIO4) -> 220R -> Green LED anode
 *
 * Required libraries (Arduino Library Manager):
 *   - Adafruit GFX Library
 *   - Adafruit SSD1306
 *
 * The MPU-6500 is talked to directly over Wire (no extra library needed) so
 * the project stays small and the I2C details stay visible.
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <math.h>

// --- Pins ---------------------------------------------------------------
static const int PIN_SDA       = 6;   // D4 on the XIAO silkscreen
static const int PIN_SCL       = 7;   // D5 on the XIAO silkscreen
static const int PIN_LEVEL_LED = 4;   // D2 on the XIAO silkscreen

// --- I2C addresses ------------------------------------------------------
static const uint8_t MPU_ADDR  = 0x68;
static const uint8_t OLED_ADDR = 0x3C;

// --- MPU-6500 registers -------------------------------------------------
static const uint8_t MPU_REG_PWR_MGMT_1   = 0x6B;
static const uint8_t MPU_REG_ACCEL_CONFIG = 0x1C;
static const uint8_t MPU_REG_ACCEL_XOUT_H = 0x3B;

// At the default +/-2 g range the sensitivity is 16384 LSB per g.
static const float ACCEL_LSB_PER_G = 16384.0f;

// --- OLED ---------------------------------------------------------------
static const int SCREEN_W = 128;
static const int SCREEN_H = 64;
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

// --- Bubble / level tuning ----------------------------------------------
// Center of the "vial" on the OLED.
static const int CENTER_X = SCREEN_W / 2;
static const int CENTER_Y = SCREEN_H / 2;
static const int VIAL_RADIUS   = 28;   // outer ring drawn around the bubble
static const int BUBBLE_RADIUS = 6;
static const int TARGET_RADIUS = 9;    // small ring marking dead-on level

// Degrees of tilt that move the bubble all the way to the edge of the vial.
static const float FULL_SCALE_DEG = 15.0f;

// Hysteresis for the "level" LED: turn ON below LEVEL_ON_DEG, OFF only
// above LEVEL_OFF_DEG. The gap stops the LED chattering on noise.
static const float LEVEL_ON_DEG  = 1.0f;
static const float LEVEL_OFF_DEG = 1.5f;
bool isLevel = false;

// --------------------------------------------------------------------- //
// I2C helpers for the MPU-6500
// --------------------------------------------------------------------- //
static void mpuWrite(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

static bool mpuReadAccel(float &ax_g, float &ay_g, float &az_g) {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(MPU_REG_ACCEL_XOUT_H);
  if (Wire.endTransmission(false) != 0) {
    return false;
  }
  // Six bytes: AX_H, AX_L, AY_H, AY_L, AZ_H, AZ_L.
  if (Wire.requestFrom((int)MPU_ADDR, 6) != 6) {
    return false;
  }
  int16_t ax_raw = (int16_t)((Wire.read() << 8) | Wire.read());
  int16_t ay_raw = (int16_t)((Wire.read() << 8) | Wire.read());
  int16_t az_raw = (int16_t)((Wire.read() << 8) | Wire.read());

  ax_g = ax_raw / ACCEL_LSB_PER_G;
  ay_g = ay_raw / ACCEL_LSB_PER_G;
  az_g = az_raw / ACCEL_LSB_PER_G;
  return true;
}

// --------------------------------------------------------------------- //
// Setup
// --------------------------------------------------------------------- //
void setup() {
  Serial.begin(115200);
  delay(200);

  pinMode(PIN_LEVEL_LED, OUTPUT);
  digitalWrite(PIN_LEVEL_LED, LOW);

  // Bring up the shared I2C bus.
  Wire.begin(PIN_SDA, PIN_SCL);
  Wire.setClock(400000);  // 400 kHz fast mode, both devices support it.

  // Wake the MPU-6500: clear the sleep bit and select PLL clock.
  mpuWrite(MPU_REG_PWR_MGMT_1, 0x01);
  delay(50);
  // Accelerometer range: +/-2 g (highest sensitivity, perfect for tilt).
  mpuWrite(MPU_REG_ACCEL_CONFIG, 0x00);

  // Bring up the OLED.
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println(F("SSD1306 not found on I2C bus."));
    while (true) {
      digitalWrite(PIN_LEVEL_LED, !digitalRead(PIN_LEVEL_LED));
      delay(150);
    }
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(8, 28);
  display.println(F("OLED Spirit Level"));
  display.display();
  delay(800);
}

// --------------------------------------------------------------------- //
// Drawing
// --------------------------------------------------------------------- //
static void drawFrame(float pitch_deg, float roll_deg, bool levelNow) {
  display.clearDisplay();

  // Outer ring: the "vial" the bubble lives inside.
  display.drawCircle(CENTER_X, CENTER_Y, VIAL_RADIUS, SSD1306_WHITE);
  // Inner target ring: the bubble fits here when perfectly level.
  display.drawCircle(CENTER_X, CENTER_Y, TARGET_RADIUS, SSD1306_WHITE);
  // Crosshairs.
  display.drawFastHLine(CENTER_X - VIAL_RADIUS, CENTER_Y,
                        2 * VIAL_RADIUS + 1, SSD1306_WHITE);
  display.drawFastVLine(CENTER_X, CENTER_Y - VIAL_RADIUS,
                        2 * VIAL_RADIUS + 1, SSD1306_WHITE);

  // Map tilt -> bubble offset. Bubble goes to the HIGH side, so a positive
  // pitch (nose up) moves it up on screen (negative Y).
  float nx = constrain(roll_deg / FULL_SCALE_DEG, -1.0f, 1.0f);
  float ny = constrain(pitch_deg / FULL_SCALE_DEG, -1.0f, 1.0f);

  int bx = CENTER_X + (int)(nx * (VIAL_RADIUS - BUBBLE_RADIUS));
  int by = CENTER_Y - (int)(ny * (VIAL_RADIUS - BUBBLE_RADIUS));

  // Filled bubble.
  display.fillCircle(bx, by, BUBBLE_RADIUS, SSD1306_WHITE);

  // Small status badge at the top.
  display.setCursor(0, 0);
  if (levelNow) {
    display.print(F("LEVEL"));
  } else {
    display.print(F("tilt "));
    display.print(fabs(pitch_deg) > fabs(roll_deg) ? pitch_deg : roll_deg, 1);
    display.print((char)247);  // degree symbol in the default font
  }

  display.display();
}

// --------------------------------------------------------------------- //
// Loop
// --------------------------------------------------------------------- //
void loop() {
  float ax, ay, az;
  if (!mpuReadAccel(ax, ay, az)) {
    Serial.println(F("IMU read failed"));
    delay(100);
    return;
  }

  // Tilt angles from the gravity vector.
  //   pitch = rotation around X axis (nose up / down)
  //   roll  = rotation around Y axis (left / right)
  float pitch_deg = atan2f(ay, sqrtf(ax * ax + az * az)) * 180.0f / (float)PI;
  float roll_deg  = atan2f(ax, sqrtf(ay * ay + az * az)) * 180.0f / (float)PI;

  // Level LED with hysteresis.
  float worst = max(fabsf(pitch_deg), fabsf(roll_deg));
  if (!isLevel && worst < LEVEL_ON_DEG) {
    isLevel = true;
  } else if (isLevel && worst > LEVEL_OFF_DEG) {
    isLevel = false;
  }
  digitalWrite(PIN_LEVEL_LED, isLevel ? HIGH : LOW);

  drawFrame(pitch_deg, roll_deg, isLevel);

  // ~30 fps is smooth enough for the bubble and gentle on I2C.
  delay(33);
}

// =====================================================================
// Two-ESP32 Walkie-Talkie Lights
// =====================================================================
// Flash this sketch TWICE - once per board - changing the ROLE define.
//
//   Board A: XIAO ESP32-C3   -> uncomment ROLE_XIAO,    comment ROLE_NODEMCU
//   Board B: ESP32 NodeMCU   -> uncomment ROLE_NODEMCU, comment ROLE_XIAO
//
// In this build the XIAO is ONLY the remote (sends button presses) and
// the NodeMCU is ONLY the lamp (runs the web server, drives the LED).
// The XIAO does not run a web server. The bidirectional version lives
// in the "Things to change once it works" section.
//
// We avoid the IP chicken-and-egg using mDNS: the NodeMCU advertises
// itself as "nodemcu-lamp.local" on the LAN, and the XIAO talks to that
// name instead of a hardcoded IP. No re-flash cycle, no DHCP guesswork.
// =====================================================================

// ---- PICK ONE ROLE BEFORE UPLOADING -------------------------------
#define ROLE_XIAO       // <-- uncomment when flashing the XIAO
// #define ROLE_NODEMCU // <-- uncomment when flashing the NodeMCU
// -------------------------------------------------------------------

#include <WiFi.h>

const char* WIFI_SSID = "GeeFam";
// TODO: replace PASSWORD_HERE with the GeeFam password before flashing.
const char* WIFI_PASS = "PASSWORD_HERE";

// mDNS hostname the NodeMCU advertises; the XIAO calls it by this name.
const char* LAMP_HOSTNAME = "nodemcu-lamp";

#if defined(ROLE_XIAO)
  #include <HTTPClient.h>
  const int BUTTON_PIN = 4;   // XIAO D2 = GPIO4, wired to button (other leg to GND)
#elif defined(ROLE_NODEMCU)
  #include <WebServer.h>
  #include <ESPmDNS.h>
  const int LED_PIN = 16;     // NodeMCU GPIO16 -> 220R -> LED anode; cathode -> GND
  WebServer server(80);
  bool ledOn = false;
#else
  #error "Uncomment exactly one of ROLE_XIAO or ROLE_NODEMCU."
#endif

#if defined(ROLE_NODEMCU)
void applyLed() {
  digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
}

void handleRoot() {
  server.send(200, "text/plain",
    String("NodeMCU lamp. LED is ") + (ledOn ? "ON" : "OFF"));
}

void handleOn() {
  ledOn = true;
  applyLed();
  Serial.println("[HTTP] /led/on  -> LED ON");
  server.send(200, "text/plain", "OK on");
}

void handleOff() {
  ledOn = false;
  applyLed();
  Serial.println("[HTTP] /led/off -> LED OFF");
  server.send(200, "text/plain", "OK off");
}

void handleToggle() {
  ledOn = !ledOn;
  applyLed();
  Serial.print("[HTTP] /led/toggle -> LED ");
  Serial.println(ledOn ? "ON" : "OFF");
  server.send(200, "text/plain", ledOn ? "OK on" : "OK off");
}
#endif

void connectWiFi() {
  Serial.print("Connecting to WiFi ");
  Serial.print(WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(400);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("WiFi connected. IP = ");
  Serial.println(WiFi.localIP());
}

void setup() {
  Serial.begin(115200);
  delay(300);

#if defined(ROLE_NODEMCU)
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
#endif

#if defined(ROLE_XIAO)
  pinMode(BUTTON_PIN, INPUT_PULLUP);
#endif

  connectWiFi();

#if defined(ROLE_NODEMCU)
  if (!MDNS.begin(LAMP_HOSTNAME)) {
    Serial.println("mDNS start failed - falling back to plain IP.");
  } else {
    Serial.print("mDNS up: http://");
    Serial.print(LAMP_HOSTNAME);
    Serial.println(".local/");
  }
  server.on("/", handleRoot);
  server.on("/led/on",     handleOn);
  server.on("/led/off",    handleOff);
  server.on("/led/toggle", handleToggle);
  server.begin();
  Serial.println("HTTP server started on port 80.");
#endif

#if defined(ROLE_XIAO)
  Serial.print("Will talk to http://");
  Serial.print(LAMP_HOSTNAME);
  Serial.println(".local/led/toggle");
#endif
}

#if defined(ROLE_XIAO)
void sendToggleToPeer() {
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("WiFi down, skipping send.");
    return;
  }
  HTTPClient http;
  String url = String("http://") + LAMP_HOSTNAME + ".local/led/toggle";
  Serial.print("-> GET ");
  Serial.println(url);
  http.begin(url);
  http.setTimeout(2000);
  int code = http.GET();
  if (code > 0) {
    Serial.print("   peer replied ");
    Serial.print(code);
    Serial.print(" : ");
    Serial.println(http.getString());
  } else {
    Serial.print("   request failed: ");
    Serial.println(http.errorToString(code));
  }
  http.end();
}
#endif

void loop() {
#if defined(ROLE_NODEMCU)
  server.handleClient();
#endif

#if defined(ROLE_XIAO)
  // Simple debounce: remember last reading and the last change time.
  static int  lastStable    = HIGH;
  static int  lastReading   = HIGH;
  static unsigned long lastChangeMs = 0;
  const unsigned long debounceMs = 40;

  int reading = digitalRead(BUTTON_PIN);
  if (reading != lastReading) {
    lastChangeMs = millis();
    lastReading  = reading;
  }
  if ((millis() - lastChangeMs) > debounceMs && reading != lastStable) {
    lastStable = reading;
    if (lastStable == LOW) {
      // Pressed (active-LOW thanks to INPUT_PULLUP).
      Serial.println("Button pressed.");
      sendToggleToPeer();
    }
  }
#endif

  delay(5);
}

/*
 * Hallway Weather Window
 * ----------------------
 * Top row of the LCD shows live indoor temperature + humidity from a DHT11.
 * Bottom row scrolls a short outdoor-weather summary pulled from Open-Meteo
 * (free, no API key) over HTTPS. If rain is forecast in the next 12 hours,
 * a relay closes and turns on a 5V LED "rain warning light".
 *
 * Board:  ESP32 NodeMCU-32S
 * Wiring: see wiring_diagram in the project record. Pins must match:
 *   LCD SDA -> GPIO 21    LCD SCL -> GPIO 22
 *   DHT11 DATA -> GPIO 4
 *   Relay IN   -> GPIO 25  (active-LOW: LOW = closed)
 *   Status LED -> GPIO 2   (via 220R to GND)
 *
 * Libraries needed (Arduino Library Manager):
 *   - "LiquidCrystal I2C" by Frank de Brabander
 *   - "DHT sensor library" by Adafruit  (+ "Adafruit Unified Sensor")
 *   - "ArduinoJson" by Benoit Blanchon (v6.x)
 *
 * Note on HTTPS: we use WiFiClientSecure with setInsecure(). This skips
 * certificate validation, which is fine for a hobby weather widget.
 * For a production-ish project you would pin the Open-Meteo root CA.
 */

#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>
#include <ArduinoJson.h>

// ---------- user-edit area ----------
const char* WIFI_SSID     = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";

// Lat/lon for the forecast. Defaults: roughly Manchester, UK.
// Change to your hallway's latitude/longitude (Google "lat lon <town>").
const float LAT = 53.48f;
const float LON = -2.24f;

// If the chance of rain in any of the next 12 hours is >= this, warn.
const int RAIN_THRESHOLD_PERCENT = 50;
// ------------------------------------

// Pin assignments (must match the wiring diagram exactly)
const int PIN_DHT        = 4;
const int PIN_RELAY      = 25;
const int PIN_STATUS_LED = 2;

#define DHTTYPE DHT11
DHT dht(PIN_DHT, DHTTYPE);

// LCD backpacks are usually 0x27 or 0x3F. We probe at boot and then
// construct the real LCD object once we know which address answered.
LiquidCrystal_I2C* lcd = nullptr;
uint8_t lcdAddr = 0x00;

// Timing
unsigned long lastSensorReadMs   = 0;
unsigned long lastWeatherFetchMs = 0;
unsigned long lastScrollStepMs   = 0;
const unsigned long SENSOR_INTERVAL_MS  = 2000UL;               // every 2 s
const unsigned long WEATHER_INTERVAL_MS = 10UL * 60UL * 1000UL; // every 10 min
const unsigned long SCROLL_INTERVAL_MS  = 350UL;

// State we render
float   indoorTempC  = NAN;
float   indoorHumid  = NAN;
String  outdoorLine  = "Connecting...";
int     scrollOffset = 0;
bool    rainWarning  = false;

// Forward declarations
void connectWiFi();
void fetchWeather();
void renderTopRow();
void renderBottomRow();
bool probeI2C(uint8_t addr);

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println(F("Hallway Weather Window booting..."));

  // Relay safety: set HIGH (inactive on active-LOW board) BEFORE setting OUTPUT,
  // so the relay doesn't click on momentarily at power-up.
  digitalWrite(PIN_RELAY, HIGH);
  pinMode(PIN_RELAY, OUTPUT);
  digitalWrite(PIN_RELAY, HIGH);  // belt and braces

  // GPIO 2 is a strapping pin: must be LOW or floating at boot for normal
  // flash boot. We wire it as LED+220R to GND (pulls low), and only drive
  // it AFTER setup begins, so we never fight the boot strap.
  pinMode(PIN_STATUS_LED, OUTPUT);
  digitalWrite(PIN_STATUS_LED, LOW);

  // I2C + LCD probe
  Wire.begin(21, 22);
  if (probeI2C(0x27)) {
    lcdAddr = 0x27;
  } else if (probeI2C(0x3F)) {
    lcdAddr = 0x3F;
  } else {
    Serial.println(F("LCD not found on 0x27 or 0x3F. Check wiring."));
    lcdAddr = 0x27;  // try anyway; init will just be a no-op visually
  }
  lcd = new LiquidCrystal_I2C(lcdAddr, 16, 2);
  lcd->init();
  lcd->backlight();
  lcd->clear();
  lcd->setCursor(0, 0);
  lcd->print(F("Hallway Window"));
  lcd->setCursor(0, 1);
  lcd->print(F("Booting..."));
  Serial.print(F("LCD initialised at 0x"));
  Serial.println(lcdAddr, HEX);

  // DHT
  dht.begin();

  // WiFi
  connectWiFi();

  // First weather fetch immediately
  fetchWeather();
}

void loop() {
  unsigned long now = millis();

  // 1. Read the DHT11 every 2 seconds.
  if (now - lastSensorReadMs >= SENSOR_INTERVAL_MS) {
    lastSensorReadMs = now;
    float t = dht.readTemperature();   // Celsius
    float h = dht.readHumidity();
    if (!isnan(t) && !isnan(h)) {
      indoorTempC = t;
      indoorHumid = h;
    } else {
      Serial.println(F("DHT11 read failed."));
    }
    renderTopRow();
  }

  // 2. Refresh the outdoor forecast every 10 minutes.
  if (now - lastWeatherFetchMs >= WEATHER_INTERVAL_MS) {
    lastWeatherFetchMs = now;
    fetchWeather();
  }

  // 3. Scroll the bottom row.
  if (now - lastScrollStepMs >= SCROLL_INTERVAL_MS) {
    lastScrollStepMs = now;
    renderBottomRow();
  }

  // 4. Keep WiFi alive.
  if (WiFi.status() != WL_CONNECTED) {
    connectWiFi();
  }
}

bool probeI2C(uint8_t addr) {
  Wire.beginTransmission(addr);
  return (Wire.endTransmission() == 0);
}

void connectWiFi() {
  if (WiFi.status() == WL_CONNECTED) return;

  Serial.print(F("Connecting to WiFi "));
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 20000UL) {
    digitalWrite(PIN_STATUS_LED, !digitalRead(PIN_STATUS_LED));
    delay(250);
    Serial.print('.');
  }
  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {
    digitalWrite(PIN_STATUS_LED, LOW);
    Serial.print(F("WiFi up. IP = "));
    Serial.println(WiFi.localIP());
  } else {
    digitalWrite(PIN_STATUS_LED, HIGH);  // stuck-on = failure mode
    outdoorLine = "No WiFi - check creds";
    Serial.println(F("WiFi failed within 20s."));
  }
}

void fetchWeather() {
  if (WiFi.status() != WL_CONNECTED) {
    outdoorLine = "Offline";
    return;
  }

  digitalWrite(PIN_STATUS_LED, HIGH);  // "talking to internet" indicator

  // Open-Meteo over HTTPS. We accept any cert via setInsecure() because
  // this is a hobby project; an attacker faking the weather isn't a real
  // threat model here.
  WiFiClientSecure client;
  client.setInsecure();

  // Open-Meteo: current temperature + next-12h precipitation probability.
  String url = "https://api.open-meteo.com/v1/forecast?latitude=";
  url += String(LAT, 4);
  url += "&longitude=";
  url += String(LON, 4);
  url += "&current=temperature_2m,weather_code";
  url += "&hourly=precipitation_probability&forecast_days=2&timezone=auto";

  HTTPClient http;
  http.setTimeout(8000);
  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
  if (!http.begin(client, url)) {
    outdoorLine = "HTTPS begin failed";
    digitalWrite(PIN_STATUS_LED, LOW);
    return;
  }
  int code = http.GET();
  Serial.print(F("HTTP code: "));
  Serial.println(code);

  if (code != 200) {
    outdoorLine = "Weather API err " + String(code);
    http.end();
    digitalWrite(PIN_STATUS_LED, LOW);
    return;
  }

  // The response is a few KB - 8 KB is plenty for 48 hourly entries.
  StaticJsonDocument<8192> doc;
  DeserializationError err = deserializeJson(doc, http.getStream());
  http.end();

  if (err) {
    outdoorLine = "JSON parse fail";
    Serial.print(F("JSON error: "));
    Serial.println(err.c_str());
    digitalWrite(PIN_STATUS_LED, LOW);
    return;
  }

  float outdoorTemp = doc["current"]["temperature_2m"] | NAN;
  int   wxCode      = doc["current"]["weather_code"]    | -1;

  // Find the worst precipitation probability across the next 12 hours.
  int maxPop = 0;
  JsonArray pops = doc["hourly"]["precipitation_probability"].as<JsonArray>();
  int hoursToCheck = (int)pops.size() < 12 ? (int)pops.size() : 12;
  for (int i = 0; i < hoursToCheck; ++i) {
    int v = pops[i] | 0;
    if (v > maxPop) maxPop = v;
  }

  // Decide on the rain warning light.
  rainWarning = (maxPop >= RAIN_THRESHOLD_PERCENT);
  // Active-LOW: LOW closes the relay, energising the LED strip.
  digitalWrite(PIN_RELAY, rainWarning ? LOW : HIGH);

  // Build the scrolling outdoor string.
  String wx = "Out ";
  if (!isnan(outdoorTemp)) {
    wx += String(outdoorTemp, 1);
    wx += (char)223;   // degree symbol on HD44740 charset
    wx += "C  ";
  }
  wx += "Rain 12h: ";
  wx += String(maxPop);
  wx += "%   ";
  wx += rainWarning ? "** RAIN WARNING **" : "Looking dry";
  wx += "   (wx code ";
  wx += String(wxCode);
  wx += ")   ";

  outdoorLine = wx;
  scrollOffset = 0;

  Serial.print(F("Outdoor line: "));
  Serial.println(outdoorLine);

  digitalWrite(PIN_STATUS_LED, LOW);
}

void renderTopRow() {
  if (!lcd) return;
  lcd->setCursor(0, 0);
  char buf[17];
  if (isnan(indoorTempC) || isnan(indoorHumid)) {
    snprintf(buf, sizeof(buf), "In: --.- C --%%RH");
  } else {
    // Clamp humidity to 0..99 so the field stays 2 chars wide and the
    // whole line fits 16 chars even at edge values.
    int humPct = (int)indoorHumid;
    if (humPct < 0)  humPct = 0;
    if (humPct > 99) humPct = 99;
    // e.g. "In:21.4C  43%RH " (exactly 16 chars after padding)
    snprintf(buf, sizeof(buf), "In:%4.1fC %2d%%RH",
             indoorTempC, humPct);
  }
  // Pad to 16 chars
  for (int i = strlen(buf); i < 16; ++i) buf[i] = ' ';
  buf[16] = '\0';
  lcd->print(buf);
}

void renderBottomRow() {
  if (!lcd) return;
  if (outdoorLine.length() == 0) return;

  // Build a 16-char window into outdoorLine, wrapping around.
  int n = outdoorLine.length();
  String window;
  window.reserve(17);
  for (int i = 0; i < 16; ++i) {
    window += outdoorLine[(scrollOffset + i) % n];
  }
  lcd->setCursor(0, 1);
  lcd->print(window);

  scrollOffset = (scrollOffset + 1) % n;
}

// MqttSensorPublisher.ino
//
// XIAO ESP32-C3 reads a DHT11 every 30 seconds and publishes
// temperature + humidity to the Mosquitto broker running on the
// Orange Pi One. This is the "leaf endpoint" half of the project;
// the Orange Pi is the "hub" running mosquitto on port 1883.
//
// Topics published:
//   home/livingroom/temperature   (float, degC, retained)
//   home/livingroom/humidity      (float, %RH,  retained)
//   home/livingroom/status        ("online" / "offline" via LWT)
//
// Subscribe from any machine on GeeFam to watch live:
//   mosquitto_sub -h <pi-ip> -t 'home/livingroom/#' -v
//
// Libraries required (Arduino Library Manager):
//   - PubSubClient   by Nick O'Leary
//   - DHT sensor library by Adafruit  (+ Adafruit Unified Sensor)

#include <WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>

// ---------- User config ----------
const char* WIFI_SSID     = "GeeFam";
const char* WIFI_PASSWORD = "PASSWORD_HERE";

// Set this to the Orange Pi's IP shown on the router admin page
// after first boot. Update once and reflash.
const char* MQTT_HOST = "192.168.88.40";
const uint16_t MQTT_PORT = 1883;

const char* MQTT_CLIENT_ID = "xiao-livingroom";
const char* TOPIC_TEMP     = "home/livingroom/temperature";
const char* TOPIC_HUM      = "home/livingroom/humidity";
const char* TOPIC_STATUS   = "home/livingroom/status";

const uint32_t PUBLISH_INTERVAL_MS = 30000;  // 30 s

// ---------- Wiring ----------
// DHT11 DATA -> XIAO GPIO 3 (silkscreen "D1")
// DHT11 VCC  -> XIAO 3V3
// DHT11 GND  -> XIAO GND
// 10K pull-up between DATA and 3V3 (skip if your DHT11 module already has one)
const uint8_t DHT_PIN  = 3;
const uint8_t DHT_TYPE = DHT11;

DHT dht(DHT_PIN, DHT_TYPE);
WiFiClient wifiClient;
PubSubClient mqtt(wifiClient);

uint32_t lastPublishMs = 0;

void connectWifi() {
  Serial.print("WiFi: connecting to ");
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("WiFi: IP=");
  Serial.println(WiFi.localIP());
}

void connectMqtt() {
  mqtt.setServer(MQTT_HOST, MQTT_PORT);
  while (!mqtt.connected()) {
    Serial.print("MQTT: connecting to ");
    Serial.print(MQTT_HOST);
    Serial.print(":");
    Serial.print(MQTT_PORT);
    Serial.print(" ... ");
    // Last-will: if we vanish, broker publishes "offline" so the Pi
    // (or a dashboard) knows this node went away.
    bool ok = mqtt.connect(
      MQTT_CLIENT_ID,
      nullptr, nullptr,                 // no user / password yet
      TOPIC_STATUS, 1, true, "offline"  // LWT topic, QoS, retained, payload
    );
    if (ok) {
      Serial.println("connected");
      mqtt.publish(TOPIC_STATUS, "online", true);
    } else {
      Serial.print("failed rc=");
      Serial.print(mqtt.state());
      Serial.println(" - retrying in 3 s");
      delay(3000);
    }
  }
}

void publishReading() {
  float tC = dht.readTemperature();
  float rh = dht.readHumidity();

  if (isnan(tC) || isnan(rh)) {
    Serial.println("DHT: read failed (NaN) - skipping");
    return;
  }

  char buf[16];

  dtostrf(tC, 0, 1, buf);
  mqtt.publish(TOPIC_TEMP, buf, true);   // retained = newcomers get last value
  Serial.print("publish ");
  Serial.print(TOPIC_TEMP);
  Serial.print(" = ");
  Serial.println(buf);

  dtostrf(rh, 0, 1, buf);
  mqtt.publish(TOPIC_HUM, buf, true);
  Serial.print("publish ");
  Serial.print(TOPIC_HUM);
  Serial.print(" = ");
  Serial.println(buf);
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("=== XIAO ESP32-C3 -> Orange Pi MQTT publisher ===");
  dht.begin();
  connectWifi();
  connectMqtt();
  publishReading();           // send one immediately so we see life
  lastPublishMs = millis();
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    connectWifi();
  }
  if (!mqtt.connected()) {
    connectMqtt();
  }
  mqtt.loop();

  uint32_t now = millis();
  if (now - lastPublishMs >= PUBLISH_INTERVAL_MS) {
    publishReading();
    lastPublishMs = now;
  }
}

// JoystickDoodle - paint on a 128x64 OLED with a 2-axis joystick
//
// Move the stick to move a cursor. Press the joystick button to toggle
// "pen down" mode - while pen is down, the cursor leaves a trail.
// Hold the button for 1 second to clear the screen.
//
// Hardware: ESP32 NodeMCU-32S + 0.96" SSD1306 I2C OLED + analog joystick
// Libraries: Adafruit_GFX, Adafruit_SSD1306 (install via Library Manager)
//
// Drawing strategy (kept simple on purpose):
//   We keep our OWN canvas as a bool[128][64] - one cell per OLED pixel.
//   Each frame we:
//     1. clear the OLED buffer
//     2. copy our canvas onto the buffer (every "drawn" pixel)
//     3. stamp the blinking cursor on top
//     4. push the buffer to the screen with display()
//   This avoids any "save/restore the pixel under the cursor" trickery,
//   so the cursor can never leave phantom dots behind.

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ----- Pin map (MUST match the wiring diagram) -----
const int PIN_VRX = 34;   // joystick X axis -> ADC1_CH6 (input-only pin)
const int PIN_VRY = 35;   // joystick Y axis -> ADC1_CH7 (input-only pin)
const int PIN_SW  = 32;   // joystick button (active LOW, needs internal pull-up)
const int PIN_SDA = 21;   // OLED I2C data
const int PIN_SCL = 22;   // OLED I2C clock

// ----- Display setup -----
const int SCREEN_W = 128;
const int SCREEN_H = 64;
const int OLED_ADDR = 0x3C;   // common SSD1306 address; some clones use 0x3D
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

// ----- Our own canvas: true = the pen has drawn here -----
bool canvas[SCREEN_W][SCREEN_H];

// ----- Cursor + pen state -----
// Use float for sub-pixel movement so a slow stick push still scrolls smoothly.
float cursorX = 64.0f;        // start in the middle of a 128-wide screen
float cursorY = 32.0f;        // start in the middle of a 64-tall screen
bool penDown = false;

// ----- Button debounce + long-press -----
bool      lastButton    = HIGH;   // pull-up means HIGH = released
uint32_t  buttonDownAt  = 0;
bool      longHandled   = false;
const uint32_t LONG_PRESS_MS = 1000;

void clearCanvas() {
  for (int x = 0; x < SCREEN_W; x++) {
    for (int y = 0; y < SCREEN_H; y++) {
      canvas[x][y] = false;
    }
  }
}

void setup() {
  Serial.begin(115200);
  delay(200);

  pinMode(PIN_SW, INPUT_PULLUP);

  // ESP32 ADC: default is 12-bit (0..4095) with ~3.3V full scale
  analogReadResolution(12);
  analogSetAttenuation(ADC_11db);

  Wire.begin(PIN_SDA, PIN_SCL);

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("SSD1306 not found - check wiring and address");
    while (true) { delay(1000); }
  }

  clearCanvas();

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Joystick Doodle");
  display.println("Click=pen, hold=clear");
  display.display();
  delay(1500);
  display.clearDisplay();
  display.display();
}

void loop() {
  // ---- Read axes ----
  // ESP32 ADC midpoint is ~2048. Anything within DEADZONE counts as "centered".
  int rawX = analogRead(PIN_VRX);
  int rawY = analogRead(PIN_VRY);
  int dx = rawX - 2048;
  int dy = rawY - 2048;
  const int DEADZONE = 250;
  if (abs(dx) < DEADZONE) dx = 0;
  if (abs(dy) < DEADZONE) dy = 0;

  // Map raw delta to a small per-loop step. 2048 maps to ~3 pixels/loop.
  // Y axis is inverted so pushing the stick up moves the cursor up.
  float stepX = (float)dx / 700.0f;
  float stepY = -(float)dy / 700.0f;

  cursorX += stepX;
  cursorY += stepY;

  // Clamp to screen
  if (cursorX < 0)            cursorX = 0;
  if (cursorX > SCREEN_W - 1) cursorX = SCREEN_W - 1;
  if (cursorY < 0)            cursorY = 0;
  if (cursorY > SCREEN_H - 1) cursorY = SCREEN_H - 1;

  // ---- Read button ----
  bool button = digitalRead(PIN_SW);   // LOW when pressed
  uint32_t now = millis();

  if (button == LOW && lastButton == HIGH) {
    // Press edge
    buttonDownAt = now;
    longHandled  = false;
  }

  if (button == LOW && !longHandled && (now - buttonDownAt) >= LONG_PRESS_MS) {
    // Long-press: wipe the canvas
    clearCanvas();
    penDown      = false;
    longHandled  = true;
  }

  if (button == HIGH && lastButton == LOW) {
    // Release edge - short press toggles the pen if long-press didn't fire
    if (!longHandled && (now - buttonDownAt) < LONG_PRESS_MS) {
      penDown = !penDown;
    }
  }
  lastButton = button;

  // ---- Update canvas ----
  // If the pen is down, mark this pixel in OUR canvas as drawn.
  int cx = (int)cursorX;
  int cy = (int)cursorY;
  if (penDown) {
    canvas[cx][cy] = true;
  }

  // ---- Render ----
  // 1) Clear the OLED buffer.
  display.clearDisplay();
  // 2) Copy our canvas onto it - every pixel the pen has touched.
  for (int x = 0; x < SCREEN_W; x++) {
    for (int y = 0; y < SCREEN_H; y++) {
      if (canvas[x][y]) display.drawPixel(x, y, SSD1306_WHITE);
    }
  }
  // 3) Blink the cursor on top. No save/restore needed - next frame
  //    starts from clearDisplay() again.
  bool showCursor = (now / 150) % 2 == 0;
  if (showCursor) {
    display.drawPixel(cx, cy, SSD1306_WHITE);
  }
  // 4) Push to the screen.
  display.display();

  delay(30);  // ~33 fps, plenty smooth for a 10-year-old to draw with
}

// =====================================================================
//  Reaction-Time Game v2 -- PROTO PCB EDITION
//  Hardware: Arduino Uno R3 on a hand-soldered double-sided proto PCB.
//
//  Pins (must match the wiring diagram):
//    D2  -> START button  (to GND when pressed, INPUT_PULLUP + ext 10K)
//    D3  -> PLAYER button (to GND when pressed, INPUT_PULLUP + ext 10K)
//    D9  -> RED LED   (WAIT / FAIL indicator), via 330R to GND
//    D10 -> GREEN LED (GO indicator),          via 330R to GND
//
//  Game:
//    1. Press START.  Red LED comes on (= "wait").
//    2. After a random 1.5 - 4.5 s, red goes off, green comes on.
//    3. Hit PLAYER as fast as you can. Reaction time printed on Serial.
//    4. Press PLAYER while red is still on = false-start: red flashes.
// =====================================================================

const uint8_t PIN_START  = 2;
const uint8_t PIN_PLAYER = 3;
const uint8_t PIN_RED    = 9;
const uint8_t PIN_GREEN  = 10;

// Indexes for the per-button debounce state arrays below.
// Pass these (not raw pin numbers) into wasPressed().
const uint8_t BTN_START_IDX  = 0;
const uint8_t BTN_PLAYER_IDX = 1;
const uint8_t NUM_BUTTONS    = 2;

enum GameState { IDLE, WAITING, GO, RESULT, FALSE_START };
GameState state = IDLE;

unsigned long waitStartMs = 0;
unsigned long waitDurationMs = 0;
unsigned long goStartMs = 0;

// Per-button debounce state, keyed by a small index (0..NUM_BUTTONS-1)
// rather than the raw GPIO pin number. This way the helper can never
// silently misbehave if a pin >= array-size were ever passed in.
bool          btnLastReading[NUM_BUTTONS] = { false, false };
bool          btnStablePressed[NUM_BUTTONS] = { false, false };
unsigned long btnLastChangeMs[NUM_BUTTONS] = { 0, 0 };

// ---- Debounced "was this button just pressed?" helper ----
// idx selects which slot in the per-button arrays to use.
bool wasPressed(uint8_t idx, uint8_t pin) {
  const unsigned long DEBOUNCE_MS = 25;
  bool reading = (digitalRead(pin) == LOW);      // active-LOW
  if (reading != btnLastReading[idx]) {
    btnLastChangeMs[idx] = millis();
    btnLastReading[idx] = reading;
  }
  bool isStable = (millis() - btnLastChangeMs[idx]) > DEBOUNCE_MS;
  bool fired = false;
  if (isStable && reading && !btnStablePressed[idx]) {
    fired = true;
    btnStablePressed[idx] = true;
  } else if (isStable && !reading) {
    btnStablePressed[idx] = false;
  }
  return fired;
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_START,  INPUT_PULLUP);
  pinMode(PIN_PLAYER, INPUT_PULLUP);
  pinMode(PIN_RED,    OUTPUT);
  pinMode(PIN_GREEN,  OUTPUT);
  digitalWrite(PIN_RED,   LOW);
  digitalWrite(PIN_GREEN, LOW);

  // Seed the RNG from a floating analog pin so the wait time isn't
  // identical every power-on.
  randomSeed(analogRead(A0));

  Serial.println(F("Reaction-Time Game (proto PCB build)"));
  Serial.println(F("Press START to begin."));
}

void loop() {
  bool startPressed  = wasPressed(BTN_START_IDX,  PIN_START);
  bool playerPressed = wasPressed(BTN_PLAYER_IDX, PIN_PLAYER);

  switch (state) {

    case IDLE:
      digitalWrite(PIN_RED,   LOW);
      digitalWrite(PIN_GREEN, LOW);
      if (startPressed) {
        waitDurationMs = random(1500, 4500);   // 1.5 - 4.5 seconds
        waitStartMs = millis();
        digitalWrite(PIN_RED, HIGH);
        Serial.print(F("Wait... "));
        state = WAITING;
      }
      break;

    case WAITING:
      // Jumped the gun?
      if (playerPressed) {
        Serial.println(F("FALSE START!"));
        digitalWrite(PIN_RED, LOW);
        state = FALSE_START;
        goStartMs = millis();   // re-use as flash timer
        break;
      }
      if (millis() - waitStartMs >= waitDurationMs) {
        digitalWrite(PIN_RED,   LOW);
        digitalWrite(PIN_GREEN, HIGH);
        goStartMs = millis();
        Serial.println(F("GO!"));
        state = GO;
      }
      break;

    case GO:
      if (playerPressed) {
        unsigned long rt = millis() - goStartMs;
        digitalWrite(PIN_GREEN, LOW);
        Serial.print(F("Reaction time: "));
        Serial.print(rt);
        Serial.println(F(" ms"));
        Serial.println(F("Press START for another go."));
        state = IDLE;
      }
      // Safety: if nobody reacts for 5s, give up.
      if (millis() - goStartMs > 5000) {
        digitalWrite(PIN_GREEN, LOW);
        Serial.println(F("Too slow, game reset."));
        state = IDLE;
      }
      break;

    case FALSE_START: {
      // Flash red 6 times over ~1.2s, then return to IDLE
      unsigned long t = millis() - goStartMs;
      digitalWrite(PIN_RED, (t / 100) % 2);
      if (t > 1200) {
        digitalWrite(PIN_RED, LOW);
        Serial.println(F("Press START to try again."));
        state = IDLE;
      }
      break;
    }

    case RESULT:
      // not used in this version, kept for future scoreboard expansion
      state = IDLE;
      break;
  }
}

// Clap-O-Meter: KY-037 microphone + OLED bar graph + loud-noise LED
// Board: ESP32 NodeMCU-32S (Arduino IDE: "ESP32 Dev Module" or "NodeMCU-32S")
//
// What it does:
//   - Reads the KY-037 analog output (GPIO34) on a fixed 1 ms tick (~1000 samples/sec).
//   - Tracks how far each sample swings away from the quiet baseline.
//   - Draws a live bar graph on the 0.96" I2C OLED.
//   - Flashes the red LED when a loud sound (clap, shout) is detected.
//
// Libraries (install via Arduino Library Manager):
//   - Adafruit SSD1306
//   - Adafruit GFX Library
//
// Wiring (matches the Mermaid diagram in description):
//   KY-037 VCC -> ESP32 3V3   (10uF cap between VCC and GND, right at the module)
//   KY-037 GND -> ESP32 GND
//   KY-037 A0  -> ESP32 GPIO 34   (input-only ADC pin, perfect for a sensor)
//   OLED VCC   -> ESP32 3V3
//   OLED GND   -> ESP32 GND
//   OLED SDA   -> ESP32 GPIO 21
//   OLED SCL   -> ESP32 GPIO 22
//   LED anode  -> 330R -> ESP32 GPIO 23
//   LED cathode-> ESP32 GND

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// --- Pin assignments (must match the wiring diagram) ---
const int PIN_MIC_AOUT = 34;   // KY-037 analog out
const int PIN_LED      = 23;   // Red LED through 330R
const int PIN_SDA      = 21;   // OLED SDA
const int PIN_SCL      = 22;   // OLED SCL

// --- OLED setup ---
const int SCREEN_W = 128;
const int SCREEN_H = 64;
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

// --- Sound tracking state ---
int baseline       = 1900;   // average "quiet" ADC reading, set during calibration
int peakLoudness   = 0;      // largest |sample - baseline| we have seen recently

// --- Timing ---
unsigned long lastSampleMs = 0;
unsigned long lastDecayMs  = 0;
unsigned long lastDrawMs   = 0;
unsigned long ledOffAtMs   = 0;

// --- Tunable thresholds ---
const int LOUD_THRESHOLD = 400;   // deviation from baseline that counts as "loud"
const int MAX_LOUDNESS   = 1500;  // anything past this maxes out the bar

void setup() {
  Serial.begin(115200);
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);

  // ESP32 ADC: 12 bit (0..4095), full 0..3.3V range
  analogReadResolution(12);
  analogSetPinAttenuation(PIN_MIC_AOUT, ADC_11db);

  Wire.begin(PIN_SDA, PIN_SCL);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found at 0x3C, halting.");
    while (true) { delay(1000); }
  }

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println("Clap-O-Meter");
  display.println("Calibrating quiet...");
  display.display();

  // Calibrate baseline: average ~1 second of samples while it is quiet.
  long sum = 0;
  const int N = 500;
  for (int i = 0; i < N; i++) {
    sum += analogRead(PIN_MIC_AOUT);
    delay(2);
  }
  baseline = sum / N;

  display.clearDisplay();
  display.setCursor(0, 0);
  display.print("Baseline: ");
  display.println(baseline);
  display.display();
  delay(800);
}

void loop() {
  unsigned long now = millis();

  // 1) Sample the mic on a steady 1 ms tick (~1000 Hz).
  //    Locking the rate makes the bar behave consistently and keeps
  //    the "samples per second" claim honest.
  int deviation = 0;
  if (now - lastSampleMs >= 1) {
    lastSampleMs = now;
    int sample = analogRead(PIN_MIC_AOUT);
    deviation = abs(sample - baseline);
    if (deviation > peakLoudness) {
      peakLoudness = deviation;
    }
  }

  // 2) Decay the peak over time so the bar falls back down between sounds.
  if (now - lastDecayMs >= 20) {
    lastDecayMs = now;
    peakLoudness -= 15;
    if (peakLoudness < 0) peakLoudness = 0;
  }

  // 3) Loud-sound LED: pulse on for 150 ms when threshold crossed.
  if (deviation > LOUD_THRESHOLD) {
    digitalWrite(PIN_LED, HIGH);
    ledOffAtMs = now + 150;
  } else if (now > ledOffAtMs) {
    digitalWrite(PIN_LED, LOW);
  }

  // 4) Redraw the OLED about 30 times per second.
  if (now - lastDrawMs >= 33) {
    lastDrawMs = now;
    drawScreen(peakLoudness);
  }
}

void drawScreen(int peak) {
  display.clearDisplay();

  // Title row
  display.setCursor(0, 0);
  display.setTextSize(1);
  display.print("Clap-O-Meter");

  // Numeric readout
  display.setCursor(80, 0);
  display.print("L:");
  display.print(peak);

  // Bar graph frame
  const int barX = 0;
  const int barY = 20;
  const int barW = 128;
  const int barH = 30;
  display.drawRect(barX, barY, barW, barH, SSD1306_WHITE);

  // Filled portion = peak loudness scaled to the bar width
  int clipped = peak;
  if (clipped > MAX_LOUDNESS) clipped = MAX_LOUDNESS;
  int fill = (long)clipped * (barW - 4) / MAX_LOUDNESS;
  display.fillRect(barX + 2, barY + 2, fill, barH - 4, SSD1306_WHITE);

  // Footer label
  display.setCursor(0, 55);
  if (peak > LOUD_THRESHOLD) {
    display.print("LOUD!  clap detected");
  } else if (peak > LOUD_THRESHOLD / 2) {
    display.print("talking / music");
  } else {
    display.print("quiet");
  }

  display.display();
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_VL53L0X.h>

// ---------- Pin map (must match the wiring diagram) ----------
const int PIN_SDA       = 21;   // ESP32 default I2C SDA
const int PIN_SCL       = 22;   // ESP32 default I2C SCL
const int PIN_LED_GREEN = 25;   // good-posture LED
const int PIN_LED_RED   = 26;   // slouch-warning LED
const int PIN_BUTTON    = 27;   // recalibrate button (active LOW, internal pull-up)

// ---------- OLED ----------
const int SCREEN_W = 128;
const int SCREEN_H = 64;
Adafruit_SSD1306 display(SCREEN_W, SCREEN_H, &Wire, -1);

// ---------- ToF sensor ----------
Adafruit_VL53L0X lox = Adafruit_VL53L0X();

// ---------- Posture state ----------
// Target distance from sensor to chest when sitting upright.
// Default 500 mm; press the button while sitting upright to recalibrate.
int targetDistance_mm = 500;

// Warning threshold: anything closer than this is "slouching".
// We define "too close" as 80 mm closer than target.
const int SLOUCH_MARGIN_MM = 80;

// VL53L0X gives noisy single reads, so we average a few.
const int SAMPLES = 4;

// Debounce
unsigned long lastButtonMs = 0;
const unsigned long DEBOUNCE_MS = 250;

int readDistanceAveraged_mm() {
  long sum = 0;
  int valid = 0;
  for (int i = 0; i < SAMPLES; i++) {
    VL53L0X_RangingMeasurementData_t m;
    lox.rangingTest(&m, false);
    if (m.RangeStatus != 4) {  // status 4 = out of range
      sum += m.RangeMilliMeter;
      valid++;
    }
    delay(15);
  }
  if (valid == 0) return -1;
  return (int)(sum / valid);
}

void drawScreen(int distance_mm, bool slouching, bool outOfRange) {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("Posture Coach");

  display.setCursor(0, 12);
  display.print("Target: ");
  display.print(targetDistance_mm);
  display.print(" mm");

  display.setTextSize(2);
  display.setCursor(0, 26);
  if (outOfRange) {
    display.print("-- mm");
  } else {
    display.print(distance_mm);
    display.print(" mm");
  }

  display.setTextSize(2);
  display.setCursor(0, 48);
  if (outOfRange) {
    display.print("STAND BACK");
  } else if (slouching) {
    display.print("SLOUCH!");
  } else {
    display.print("GOOD");
  }

  display.display();
}

void recalibrate() {
  // Take a fresh reading and treat it as the new "upright" distance.
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 24);
  display.print("Calibrating...");
  display.print("\nSit up straight!");
  display.display();
  delay(800);

  int d = readDistanceAveraged_mm();
  if (d > 0) {
    targetDistance_mm = d;
  }

  // Blink both LEDs to confirm.
  for (int i = 0; i < 3; i++) {
    digitalWrite(PIN_LED_GREEN, HIGH);
    digitalWrite(PIN_LED_RED, HIGH);
    delay(120);
    digitalWrite(PIN_LED_GREEN, LOW);
    digitalWrite(PIN_LED_RED, LOW);
    delay(120);
  }
}

void setup() {
  Serial.begin(115200);

  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);
  pinMode(PIN_BUTTON, INPUT_PULLUP);
  digitalWrite(PIN_LED_GREEN, LOW);
  digitalWrite(PIN_LED_RED, LOW);

  Wire.begin(PIN_SDA, PIN_SCL);

  // OLED
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found at 0x3C");
    while (true) { delay(1000); }
  }
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 24);
  display.print("Booting...");
  display.display();

  // VL53L0X
  if (!lox.begin()) {
    Serial.println("VL53L0X not found at 0x29");
    display.clearDisplay();
    display.setCursor(0, 24);
    display.print("VL53L0X missing");
    display.display();
    while (true) { delay(1000); }
  }

  Serial.println("Ready. Press button to recalibrate.");
}

void loop() {
  // Check button (active LOW, internal pull-up).
  if (digitalRead(PIN_BUTTON) == LOW) {
    unsigned long now = millis();
    if (now - lastButtonMs > DEBOUNCE_MS) {
      lastButtonMs = now;
      recalibrate();
    }
  }

  int d = readDistanceAveraged_mm();
  bool outOfRange = (d <= 0) || (d > 1200);  // VL53L0X tops out near 1.2-2 m
  bool slouching = false;

  if (!outOfRange) {
    // "Slouching" means measured distance is meaningfully closer than target.
    slouching = (d < (targetDistance_mm - SLOUCH_MARGIN_MM));
  }

  digitalWrite(PIN_LED_GREEN, (!outOfRange && !slouching) ? HIGH : LOW);
  digitalWrite(PIN_LED_RED,   (!outOfRange &&  slouching) ? HIGH : LOW);

  drawScreen(d, slouching, outOfRange);

  Serial.print("d=");
  Serial.print(d);
  Serial.print(" mm  target=");
  Serial.print(targetDistance_mm);
  Serial.print(" mm  slouch=");
  Serial.println(slouching ? "YES" : "no");

  delay(150);
}

/*
 * TV Remote LED Color Picker - KY-022 IR Receiver demo
 *
 * Point any household IR remote at the KY-022 and press buttons.
 * On the FIRST run, the sketch is in LEARN MODE:
 *   - Watch the Serial Monitor (115200 baud).
 *   - When prompted, point the remote and press the button you want
 *     to use for RED. Then GREEN, then BLUE, then YELLOW.
 *   - Each press is captured and stored in RAM for this session.
 *
 * After learning, every recognised press lights its matching LED for
 * one second. Unknown buttons print "?" to the Serial Monitor but do
 * not light anything - useful for discovering which codes your remote
 * actually sends.
 *
 * Reset the Arduino to re-learn with a different remote.
 *
 * Library: "IRremote" by shirriff / Armin Joachimsmeyer (v3.x or v4.x),
 * install from Arduino IDE Library Manager.
 */

#include <IRremote.hpp>   // v3+ header. Older v2.x used <IRremote.h>.

// ---------- Pin map (must match wiring diagram) ----------
const uint8_t PIN_IR     = 2;   // KY-022 signal "S" pin
const uint8_t PIN_LED_R  = 6;   // Red LED   via 330R to GND
const uint8_t PIN_LED_G  = 7;   // Green LED via 330R to GND
const uint8_t PIN_LED_B  = 8;   // Blue LED  via 330R to GND
const uint8_t PIN_LED_Y  = 9;   // Yellow LED via 330R to GND

// Order matches the learning sequence below.
const uint8_t LED_PINS[4] = { PIN_LED_R, PIN_LED_G, PIN_LED_B, PIN_LED_Y };
const char*   LED_NAMES[4] = { "RED", "GREEN", "BLUE", "YELLOW" };

// Storage for the four learned remote codes.
// 0 means "not learned yet". Most real remote codes are non-zero so
// this is safe for our purposes.
uint32_t learnedCode[4] = { 0, 0, 0, 0 };
bool     allLearned     = false;

// ---------- Helpers ----------

// Flash every LED briefly so the user can confirm wiring before
// the first learn prompt.
void wiringSelfTest() {
  for (uint8_t i = 0; i < 4; i++) {
    digitalWrite(LED_PINS[i], HIGH);
    delay(200);
    digitalWrite(LED_PINS[i], LOW);
  }
}

void allLedsOff() {
  for (uint8_t i = 0; i < 4; i++) digitalWrite(LED_PINS[i], LOW);
}

// Block until the user presses *something* and we manage to decode it.
// Returns the 32-bit decoded value. Ignores "repeat" frames so the
// user holding a button still only learns one code.
uint32_t waitForButton() {
  while (true) {
    if (IrReceiver.decode()) {
      uint32_t code = IrReceiver.decodedIRData.decodedRawData;
      bool isRepeat = IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT;
      IrReceiver.resume();
      if (code != 0 && !isRepeat) {
        return code;
      }
    }
  }
}

void runLearnMode() {
  Serial.println(F("--- LEARN MODE ---"));
  Serial.println(F("Point your remote at the sensor and press one"));
  Serial.println(F("button for each colour when prompted."));
  Serial.println();

  for (uint8_t i = 0; i < 4; i++) {
    Serial.print(F("Press the button you want for "));
    Serial.print(LED_NAMES[i]);
    Serial.println(F("..."));

    // Light the matching LED while we wait, as a visual prompt.
    digitalWrite(LED_PINS[i], HIGH);
    uint32_t code = waitForButton();
    digitalWrite(LED_PINS[i], LOW);

    learnedCode[i] = code;
    Serial.print(F("  learned 0x"));
    Serial.println(code, HEX);

    // Small pause so a long button press doesn't bleed into the next prompt.
    delay(400);
  }

  Serial.println();
  Serial.println(F("All four colours learned. Have fun!"));
  Serial.println();
  allLearned = true;
}

// ---------- Arduino entry points ----------

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 2000) { /* wait briefly for USB serial */ }

  for (uint8_t i = 0; i < 4; i++) {
    pinMode(LED_PINS[i], OUTPUT);
    digitalWrite(LED_PINS[i], LOW);
  }

  // Start the IR receiver. The LED_BUILTIN feedback flag blinks pin 13
  // every time a frame is received - handy "is it alive?" indicator.
  IrReceiver.begin(PIN_IR, ENABLE_LED_FEEDBACK);

  Serial.println();
  Serial.println(F("KY-022 TV Remote LED Color Picker"));
  Serial.println(F("================================="));
  wiringSelfTest();
  runLearnMode();
}

void loop() {
  if (!IrReceiver.decode()) return;

  uint32_t code     = IrReceiver.decodedIRData.decodedRawData;
  bool     isRepeat = IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT;
  IrReceiver.resume();

  // Ignore the "still holding the button" repeat frames so the LED
  // doesn't keep retriggering while you hold a button.
  if (isRepeat || code == 0) return;

  // Match against learned codes.
  int matched = -1;
  for (uint8_t i = 0; i < 4; i++) {
    if (code == learnedCode[i]) { matched = i; break; }
  }

  if (matched >= 0) {
    Serial.print(F("-> "));
    Serial.println(LED_NAMES[matched]);

    allLedsOff();
    digitalWrite(LED_PINS[matched], HIGH);
    delay(1000);
    digitalWrite(LED_PINS[matched], LOW);
  } else {
    Serial.print(F("? unknown code 0x"));
    Serial.println(code, HEX);
  }
}

// Invisible Tripwire Alarm
// ESP32 NodeMCU-32S + IR Obstacle Avoidance Module + 0.96" SSD1306 OLED + red LED.
// When something crosses in front of the IR module the OLED switches from a
// calm "ARMED" face to an "INTRUDER!" face, the red LED turns on, and a
// trip counter increments. State updates the moment the beam is broken or
// restored, so you get instant visible feedback by waving a hand past it.
//
// Libraries (install via Arduino IDE Library Manager):
//   - Adafruit GFX Library
//   - Adafruit SSD1306
//
// Board: ESP32 Arduino > ESP32 Dev Module (or NodeMCU-32S).

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ---------- Pins (must match the wiring diagram) ----------
const int PIN_IR_OUT = 32;   // Digital OUT from the IR Obstacle Avoidance Module
const int PIN_LED    = 25;   // Red LED via 330R to GND

// ---------- OLED ----------
const int SCREEN_WIDTH  = 128;
const int SCREEN_HEIGHT = 64;
const int OLED_I2C_ADDR = 0x3C;  // Most 0.96" SSD1306 boards
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// ---------- Sensor logic ----------
// The IR Obstacle Avoidance Module is active-LOW:
//   - No obstacle  -> OUT = HIGH
//   - Obstacle     -> OUT = LOW
const int OBSTACLE_LEVEL = LOW;

// Simple debounce so a flickery edge does not double-count
const unsigned long DEBOUNCE_MS = 40;
int           lastRawReading   = HIGH;
int           stableReading    = HIGH;
unsigned long lastChangeMs     = 0;
unsigned long tripCount        = 0;

void drawArmedFace() {
  display.clearDisplay();

  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(28, 0);
  display.print("ARMED");

  // Calm smiley: two eyes and a small smile
  display.drawCircle(48, 38, 3, SSD1306_WHITE);   // left eye
  display.drawCircle(80, 38, 3, SSD1306_WHITE);   // right eye
  display.drawLine(54, 50, 74, 50, SSD1306_WHITE);

  display.setTextSize(1);
  display.setCursor(0, 56);
  display.print("Trips: ");
  display.print(tripCount);

  display.display();
}

void drawIntruderFace() {
  display.clearDisplay();

  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(4, 0);
  display.print("INTRUDER!");

  // Wide-eyed alarmed face: big eyes and an "O" mouth
  display.fillCircle(48, 38, 4, SSD1306_WHITE);   // left eye
  display.fillCircle(80, 38, 4, SSD1306_WHITE);   // right eye
  display.drawCircle(64, 52, 5, SSD1306_WHITE);   // open mouth

  display.setTextSize(1);
  display.setCursor(0, 56);
  display.print("Trips: ");
  display.print(tripCount);

  display.display();
}

void setup() {
  Serial.begin(115200);

  pinMode(PIN_IR_OUT, INPUT);     // Module has its own pull-up
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);

  Wire.begin();                   // ESP32 default I2C: SDA=21, SCL=22

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_I2C_ADDR)) {
    Serial.println("SSD1306 not found - check wiring / I2C address");
    while (true) { delay(1000); }
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Invisible Tripwire");
  display.println("Warming up...");
  display.display();
  delay(800);

  drawArmedFace();
  Serial.println("Tripwire ready.");
}

void loop() {
  int reading = digitalRead(PIN_IR_OUT);

  // Debounce: only accept a new stable value once it has held for DEBOUNCE_MS
  if (reading != lastRawReading) {
    lastChangeMs = millis();
    lastRawReading = reading;
  }

  if ((millis() - lastChangeMs) > DEBOUNCE_MS && reading != stableReading) {
    stableReading = reading;

    if (stableReading == OBSTACLE_LEVEL) {
      tripCount++;
      digitalWrite(PIN_LED, HIGH);
      drawIntruderFace();
      Serial.print("TRIP #");
      Serial.println(tripCount);
    } else {
      digitalWrite(PIN_LED, LOW);
      drawArmedFace();
      Serial.println("Beam restored.");
    }
  }
}

// Piggy Bank Coin Counter
// Drop a coin past the TCRT5000 sensor - the OLED tallies it.
// Board: ESP32 NodeMCU-32S (3.3V logic)
//
// Libraries (install via Arduino Library Manager):
//   - Adafruit GFX Library
//   - Adafruit SSD1306

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Preferences.h>

// ---- Pin assignments (must match the wiring diagram) ----
const int PIN_TCRT_DO = 16;   // TCRT5000 digital output (active LOW when coin reflects)
const int PIN_LED     = 17;   // Green confirmation LED (with 330R)
const int PIN_SDA     = 21;   // OLED SDA (ESP32 default)
const int PIN_SCL     = 22;   // OLED SCL (ESP32 default)

// ---- OLED ----
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET   -1
#define OLED_ADDR    0x3C
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// ---- Counting state ----
Preferences prefs;            // Stores the total across reboots in NVS flash
unsigned long coinCount = 0;
int lastSensorState = HIGH;   // Idle state of the DO line is HIGH
unsigned long lastCoinMs = 0;
const unsigned long DEBOUNCE_MS = 250;  // Ignore re-triggers within 250 ms

// Cheerful messages that cycle as the bank fills
const char* cheers[] = {
  "Saving!",
  "Ka-ching!",
  "Nice!",
  "Keep going!",
  "Future you says THANKS"
};
const int NUM_CHEERS = sizeof(cheers) / sizeof(cheers[0]);

void drawScreen(const char* message) {
  display.clearDisplay();

  // Header
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println(F("PIGGY BANK"));
  display.drawLine(0, 10, 127, 10, SSD1306_WHITE);

  // Big number
  display.setTextSize(3);
  display.setCursor(0, 18);
  display.print(coinCount);

  // Footer
  display.setTextSize(1);
  display.setCursor(0, 54);
  display.print(message);

  display.display();
}

void setup() {
  Serial.begin(115200);
  delay(100);

  pinMode(PIN_TCRT_DO, INPUT);  // Module has its own pull-up
  pinMode(PIN_LED, OUTPUT);
  digitalWrite(PIN_LED, LOW);

  // Restore the saved count
  prefs.begin("piggy", false);
  coinCount = prefs.getULong("count", 0);

  // Start the OLED on the default I2C pins
  Wire.begin(PIN_SDA, PIN_SCL);
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println(F("OLED init failed - check wiring"));
    while (true) { delay(1000); }
  }

  drawScreen("Ready - drop a coin!");
  Serial.print(F("Loaded saved count: "));
  Serial.println(coinCount);
}

void loop() {
  int sensorState = digitalRead(PIN_TCRT_DO);
  unsigned long now = millis();

  // Edge detection: HIGH -> LOW means something just entered the IR beam
  if (lastSensorState == HIGH && sensorState == LOW &&
      (now - lastCoinMs) > DEBOUNCE_MS) {
    coinCount++;
    lastCoinMs = now;
    prefs.putULong("count", coinCount);   // Persist immediately

    // Flash the green LED for 120 ms
    digitalWrite(PIN_LED, HIGH);

    const char* msg = cheers[(coinCount - 1) % NUM_CHEERS];
    drawScreen(msg);

    Serial.print(F("Coin #"));
    Serial.print(coinCount);
    Serial.print(F("  ("));
    Serial.print(msg);
    Serial.println(F(")"));
  }

  // Turn the LED off 120 ms after a hit, without blocking the loop
  if (digitalRead(PIN_LED) == HIGH && (now - lastCoinMs) > 120) {
    digitalWrite(PIN_LED, LOW);
  }

  lastSensorState = sensorState;
  delay(5);  // Light de-jitter; TCRT5000 needs no faster sampling for coins
}

/*
  Porch Night-Light - KY-018 Photoresistor + Arduino Uno

  Idea: when the room gets dark, a "porch bulb" (yellow LED) fades
  ON. When it gets light again, it fades OFF. Smooth - no flickery
  on/off at the threshold.

  Wiring:
    KY-018 module   ->   Arduino Uno
      S (signal)         A0
      + (middle)         5V    <-- KY-018 wants 5V, not 3.3V
      - (GND)            GND

    LED (yellow):
      Uno pin 9  -> 220R resistor -> LED anode (long leg)
      LED cathode (short leg)     -> GND

  Notes for Andy:
   - The KY-018 is just an LDR (light-dependent resistor) in a
     voltage divider on a little PCB. The "S" pin gives an analog
     voltage. Bright light = one extreme, darkness = the other.
   - We deliberately do NOT use a hard threshold (if dark -> on).
     A real porch light that hard-switched at 1 lux would flicker
     every time a cloud passed. We smooth the reading and fade
     between two darkness thresholds instead.
   - If your KY-018 clone reads the OPPOSITE way (porch light on
     in daylight, off in the dark), flip DARK_IS_HIGH below from
     true to false. That's the only knob you need to touch.
*/

const uint8_t PIN_LDR = A0;   // KY-018 S pin
const uint8_t PIN_LED = 9;    // PWM-capable pin (yellow LED)

// --- Polarity knob -------------------------------------------------
// Most KY-018 clones: higher analog reading = darker. A few clones
// are wired the other way round. If the LED is ON in daylight and
// OFF in the dark, change this to false and re-upload.
const bool DARK_IS_HIGH = true;

// --- Smoothing -----------------------------------------------------
// Keep a running (exponential moving) average so a passing shadow
// doesn't snap the porch light on for half a second.
//   0 = frozen, 1 = no smoothing. 0.05 = gentle.
const float SMOOTHING = 0.05f;
float smoothedReading = 512.0f;  // start mid-scale

// --- Calibration ---------------------------------------------------
// At startup we watch the sensor for ~3 seconds while you COVER
// then UNCOVER it, so the sketch learns what "dark" and "bright"
// look like in your room. Press the Uno reset button to re-do it.
const unsigned long CAL_MS = 3000;
int rawMin = 1023;
int rawMax = 0;

// --- Sensitivity ---------------------------------------------------
// "darkPercent" is how dark (0-100) it has to get before the porch
// light starts coming on, and where it reaches full brightness.
const int DARK_START_PERCENT = 35;   // start glowing at 35% dark
const int DARK_FULL_PERCENT  = 80;   // fully on by 80% dark

void setup() {
  Serial.begin(115200);
  pinMode(PIN_LED, OUTPUT);
  analogWrite(PIN_LED, 0);

  // Give the Serial Monitor a beat to attach before the prompt.
  delay(500);

  Serial.println();
  Serial.println(F("=== Porch Night-Light ==="));
  Serial.println(F("Calibrating for ~3 seconds."));
  Serial.println(F("COVER the sensor with your hand,"));
  Serial.println(F("then UNCOVER it, before the countdown ends."));

  unsigned long calStart = millis();
  while (millis() - calStart < CAL_MS) {
    int v = analogRead(PIN_LDR);
    if (v < rawMin) rawMin = v;
    if (v > rawMax) rawMax = v;
    delay(10);
  }

  // If the user missed the prompt and the range is still tiny,
  // fall back to a sane default so the sketch isn't useless.
  if (rawMax - rawMin < 80) {
    Serial.println(F("(Calibration range was tiny - using defaults.)"));
    rawMin = 200;
    rawMax = 900;
  }

  Serial.print(F("Calibrated. rawMin="));
  Serial.print(rawMin);
  Serial.print(F("  rawMax="));
  Serial.print(rawMax);
  Serial.print(F("  DARK_IS_HIGH="));
  Serial.println(DARK_IS_HIGH ? F("true") : F("false"));
}

void loop() {
  int raw = analogRead(PIN_LDR);

  // Exponential moving average - cheap, easy to reason about.
  smoothedReading = smoothedReading + SMOOTHING * (raw - smoothedReading);

  // Map smoothed reading into a 0..100 "darkness percent".
  // If DARK_IS_HIGH is true, higher raw value = darker, so rawMin
  // maps to 0% dark and rawMax maps to 100% dark. If it's false,
  // we flip the map() arguments.
  int darkPercent;
  if (DARK_IS_HIGH) {
    darkPercent = map((int)smoothedReading, rawMin, rawMax, 0, 100);
  } else {
    darkPercent = map((int)smoothedReading, rawMin, rawMax, 100, 0);
  }
  darkPercent = constrain(darkPercent, 0, 100);

  // Convert darkness to LED brightness (0..255) with a gentle fade
  // region between DARK_START_PERCENT and DARK_FULL_PERCENT.
  int brightness;
  if (darkPercent <= DARK_START_PERCENT) {
    brightness = 0;                              // bright outside, lamp off
  } else if (darkPercent >= DARK_FULL_PERCENT) {
    brightness = 255;                            // proper dark, lamp full
  } else {
    brightness = map(
        darkPercent,
        DARK_START_PERCENT, DARK_FULL_PERCENT,
        0,                  255
    );
  }

  analogWrite(PIN_LED, brightness);

  // Log every ~250 ms so the Serial Monitor doesn't drown.
  static unsigned long lastPrint = 0;
  if (millis() - lastPrint > 250) {
    lastPrint = millis();
    Serial.print(F("raw="));      Serial.print(raw);
    Serial.print(F("  smooth=")); Serial.print((int)smoothedReading);
    Serial.print(F("  dark%="));  Serial.print(darkPercent);
    Serial.print(F("  led="));    Serial.println(brightness);
  }

  delay(20);  // ~50 Hz sample rate
}

// Laser Tripwire Alarm
// ----------------------------------------------------------
// KY-008 laser shines across a doorway into an LM393-based
// photoresistor module. While the beam hits the LDR, the
// module's DO pin reads LOW. Break the beam (walk through it)
// and DO flips HIGH -> we latch a red alarm LED on.
// Press the re-arm button to clear the alarm.
//
// Board: ESP32 NodeMCU-32S (3.3V logic)
// Serial: 115200
// ----------------------------------------------------------

// ---- Pin map (must match the Mermaid wiring diagram) ----
const int PIN_LASER       = 23;  // KY-008 signal (drive HIGH = laser on)
const int PIN_LDR_DO      = 34;  // LM393 module DO (input-only pin, fine for digital)
const int PIN_ALARM_LED   = 22;  // Red LED through 220R to GND
const int PIN_REARM_BTN   =  4;  // Button to GND, uses internal pull-up

// ---- State ----
bool alarmLatched = false;
unsigned long lastEdgePrint = 0;

// Simple debounce for the re-arm button
const unsigned long DEBOUNCE_MS = 40;
int lastBtnReading = HIGH;
int btnStable = HIGH;
unsigned long btnChangedAt = 0;

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println(F("Laser Tripwire Alarm starting..."));

  pinMode(PIN_LASER, OUTPUT);
  pinMode(PIN_ALARM_LED, OUTPUT);
  pinMode(PIN_LDR_DO, INPUT);          // module has its own pull-up
  pinMode(PIN_REARM_BTN, INPUT_PULLUP);

  // Turn the laser ON and start with the alarm clear
  digitalWrite(PIN_LASER, HIGH);
  digitalWrite(PIN_ALARM_LED, LOW);

  Serial.println(F("Laser is ON. Aim it at the white dot on the LDR module"));
  Serial.println(F("and turn the blue trim-pot until the module's signal LED"));
  Serial.println(F("just barely turns OFF. Then block the beam to test."));
}

void loop() {
  // ---- 1. Read the photoresistor module ----
  // DO is LOW when the beam is hitting it (bright enough),
  // HIGH when the beam is broken (dark).
  int beamState = digitalRead(PIN_LDR_DO);

  if (beamState == HIGH && !alarmLatched) {
    alarmLatched = true;
    Serial.println(F(">>> TRIPWIRE BROKEN <<<"));
  }

  // ---- 2. Drive the alarm LED from the latch ----
  digitalWrite(PIN_ALARM_LED, alarmLatched ? HIGH : LOW);

  // ---- 3. Re-arm button (debounced) ----
  int reading = digitalRead(PIN_REARM_BTN);
  if (reading != lastBtnReading) {
    btnChangedAt = millis();
    lastBtnReading = reading;
  }
  if ((millis() - btnChangedAt) > DEBOUNCE_MS) {
    if (reading != btnStable) {
      btnStable = reading;
      // Falling edge = button just pressed (it pulls to GND)
      if (btnStable == LOW) {
        if (alarmLatched) {
          alarmLatched = false;
          Serial.println(F("Alarm cleared. Re-armed."));
        } else {
          Serial.println(F("Already armed. Beam is intact."));
        }
      }
    }
  }

  // ---- 4. Occasional status print so you can see it working ----
  if (millis() - lastEdgePrint > 1000) {
    lastEdgePrint = millis();
    Serial.print(F("beam="));
    Serial.print(beamState == LOW ? F("INTACT ") : F("BROKEN "));
    Serial.print(F("  alarm="));
    Serial.println(alarmLatched ? F("LATCHED") : F("clear"));
  }

  delay(5);
}

// Coin Drop Counter
// ------------------
// Optical slot sensor on GPIO 4 (digital out). Every time the beam is broken
// (a coin, a finger, a piece of card), an interrupt fires and we bump the
// count. OLED shows total drops, time since the last drop (updates live),
// the last gap between drops, and the fastest gap we've ever seen.
//
// Hardware:
//   Optical slot sensor -> ESP32 NodeMCU-32S -> 0.96" SSD1306 OLED (I2C)
//
// Wiring (must match wiring_diagram):
//   Sensor VCC  -> 3V3  (try VIN/5V if drops are being missed - see notes)
//   Sensor GND  -> GND
//   Sensor D0   -> GPIO 4
//   OLED  VCC   -> 3V3
//   OLED  GND   -> GND
//   OLED  SDA   -> GPIO 21
//   OLED  SCL   -> GPIO 22
//
// Libraries (install via Arduino Library Manager):
//   - Adafruit GFX Library
//   - Adafruit SSD1306

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1
#define OLED_ADDR     0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

const int SENSOR_PIN = 4;

// Variables touched by the ISR must be volatile.
volatile unsigned long g_count       = 0;
volatile unsigned long g_lastDropMs  = 0;
volatile unsigned long g_lastGapMs   = 0;
volatile bool          g_newDrop     = false;

// Debounce - a single coin can bounce the beam a few times on the way through.
// 40 ms is short enough to catch fast drops but long enough to ignore bounce.
const unsigned long DEBOUNCE_MS = 40;

unsigned long g_fastestGapMs = 0;   // 0 means "not set yet"
unsigned long g_lastRedrawMs = 0;

void IRAM_ATTR onBeamBreak() {
  unsigned long now = millis();
  if (now - g_lastDropMs < DEBOUNCE_MS) {
    return;  // bounce - ignore
  }
  if (g_lastDropMs != 0) {
    g_lastGapMs = now - g_lastDropMs;
  }
  g_lastDropMs = now;
  g_count++;
  g_newDrop = true;
}

// Helper: read a snapshot of the ISR-shared variables atomically.
// Hides the noInterrupts/interrupts critical section from loop() so the
// main-loop code stays easy to read.
struct DropSnapshot {
  unsigned long count;
  unsigned long lastDropMs;
  unsigned long lastGapMs;
  bool          newDrop;
};

DropSnapshot readSnapshot() {
  DropSnapshot s;
  noInterrupts();
  s.count      = g_count;
  s.lastDropMs = g_lastDropMs;
  s.lastGapMs  = g_lastGapMs;
  s.newDrop    = g_newDrop;
  g_newDrop = false;
  interrupts();
  return s;
}

void drawScreen(unsigned long count,
                unsigned long sinceLastMs,
                unsigned long lastGapMs,
                unsigned long fastestGapMs) {
  display.clearDisplay();

  // Title bar
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println(F("COIN DROP COUNTER"));
  display.drawLine(0, 10, 127, 10, SSD1306_WHITE);

  // Big count
  display.setTextSize(3);
  display.setCursor(0, 14);
  display.print(count);

  // Three stat lines, left-aligned
  display.setTextSize(1);

  display.setCursor(0, 40);
  display.print(F("Since   : "));
  if (sinceLastMs == 0) {
    display.print(F("--"));
  } else if (sinceLastMs < 10000) {
    display.print(sinceLastMs);
    display.print(F(" ms"));
  } else {
    // After 10 seconds, switch to seconds with one decimal so the
    // number doesn't run off the screen.
    display.print(sinceLastMs / 1000.0, 1);
    display.print(F(" s"));
  }

  display.setCursor(0, 49);
  display.print(F("Last gap: "));
  if (lastGapMs == 0) {
    display.print(F("--"));
  } else {
    display.print(lastGapMs);
    display.print(F(" ms"));
  }

  display.setCursor(0, 58);
  display.print(F("Best gap: "));
  if (fastestGapMs == 0) {
    display.print(F("--"));
  } else {
    display.print(fastestGapMs);
    display.print(F(" ms"));
  }

  display.display();
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println(F("Coin Drop Counter starting"));

  pinMode(SENSOR_PIN, INPUT);

  // Most slot sensor breakout boards output HIGH when the beam is clear
  // and pulse LOW when something blocks it. Trigger on the FALLING edge.
  attachInterrupt(digitalPinToInterrupt(SENSOR_PIN), onBeamBreak, FALLING);

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println(F("OLED not found - check wiring / I2C address"));
    while (true) { delay(1000); }
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println(F("Ready - drop a coin!"));
  display.display();
  delay(800);

  drawScreen(0, 0, 0, 0);
}

void loop() {
  DropSnapshot snap = readSnapshot();

  if (snap.newDrop) {
    Serial.print(F("Drop #"));
    Serial.print(snap.count);
    if (snap.lastGapMs > 0) {
      Serial.print(F("  gap "));
      Serial.print(snap.lastGapMs);
      Serial.print(F(" ms"));
      if (g_fastestGapMs == 0 || snap.lastGapMs < g_fastestGapMs) {
        g_fastestGapMs = snap.lastGapMs;
        Serial.print(F("  <-- new best!"));
      }
    }
    Serial.println();
  }

  // The "Since" line needs to tick up live, so we redraw every ~100 ms even
  // when no new drop arrived. Cheap because the OLED I2C write is fast and
  // we're not doing anything else.
  unsigned long now = millis();
  if (snap.newDrop || (now - g_lastRedrawMs) >= 100) {
    g_lastRedrawMs = now;
    unsigned long sinceLast = (snap.lastDropMs == 0) ? 0 : (now - snap.lastDropMs);
    drawScreen(snap.count, sinceLast, snap.lastGapMs, g_fastestGapMs);
  }
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// --- Pin map (must match the wiring diagram) ---
const int PIN_PIR       = 13;  // HC-SR505 OUT
const int PIN_LED_GREEN = 18;  // "holding still" LED
const int PIN_LED_RED   = 19;  // "you moved!" LED

// OLED
#define SCREEN_WIDTH  128
#define SCREEN_HEIGHT 64
#define OLED_ADDR     0x3C
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// --- Game state ---
unsigned long stillStartMs   = 0;     // when the current "still streak" began
unsigned long bestStreakMs   = 0;     // best ever streak this session
unsigned long lastMotionMs   = 0;     // last time the PIR fired
unsigned long redFlashUntil  = 0;     // red LED stays on until this millis()
bool          warmingUp      = true;  // HC-SR505 needs ~30s settle time

const unsigned long WARMUP_MS    = 30000;  // give the sensor time to stabilise
const unsigned long RED_FLASH_MS = 800;    // how long the red LED stays lit on a break

void drawScreen(const char *bigLabel, unsigned long currentMs, unsigned long bestMs) {
  display.clearDisplay();

  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Stealth Timer");
  display.drawFastHLine(0, 10, SCREEN_WIDTH, SSD1306_WHITE);

  display.setCursor(0, 16);
  display.print("State: ");
  display.println(bigLabel);

  display.setCursor(0, 30);
  display.print("Now : ");
  display.print(currentMs / 1000.0, 1);
  display.println(" s");

  display.setCursor(0, 44);
  display.print("Best: ");
  display.print(bestMs / 1000.0, 1);
  display.println(" s");

  display.display();
}

void setup() {
  Serial.begin(115200);

  pinMode(PIN_PIR, INPUT);
  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);
  digitalWrite(PIN_LED_GREEN, LOW);
  digitalWrite(PIN_LED_RED, LOW);

  Wire.begin();  // ESP32 NodeMCU-32S default: SDA=21, SCL=22
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("OLED not found - check wiring / address.");
    while (true) { delay(1000); }
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Warming up PIR...");
  display.println("Stay out of view!");
  display.display();

  stillStartMs = millis();
}

void loop() {
  unsigned long now = millis();

  // 1. Warm-up window. PIR output is noisy for the first ~30s.
  if (warmingUp) {
    if (now >= WARMUP_MS) {
      warmingUp     = false;
      stillStartMs  = now;       // reset streak clock now that we trust the sensor
      lastMotionMs  = now;
      Serial.println("PIR warmed up. Game on.");
    } else {
      // Slow pulse the red LED while warming up so you know it's not dead.
      digitalWrite(PIN_LED_RED, (now / 500) % 2);
      digitalWrite(PIN_LED_GREEN, LOW);
      delay(20);
      return;
    }
  }

  // 2. Read the sensor.
  bool motion = digitalRead(PIN_PIR) == HIGH;

  if (motion) {
    // The streak is broken.
    unsigned long streak = now - stillStartMs;
    if (streak > bestStreakMs) {
      bestStreakMs = streak;
      Serial.print("New best: ");
      Serial.print(bestStreakMs / 1000.0, 1);
      Serial.println(" s");
    }
    // Reset streak clock and arm the red LED to flash for a while.
    stillStartMs   = now;
    lastMotionMs   = now;
    redFlashUntil  = now + RED_FLASH_MS;
  }

  // 3. Drive the LEDs.
  bool redOn   = now < redFlashUntil;
  bool greenOn = !redOn;  // green = "the sensor sees nothing right now"

  digitalWrite(PIN_LED_RED,   redOn   ? HIGH : LOW);
  digitalWrite(PIN_LED_GREEN, greenOn ? HIGH : LOW);

  // 4. Update the screen ~5 times a second.
  static unsigned long lastDraw = 0;
  if (now - lastDraw >= 200) {
    lastDraw = now;
    unsigned long currentStreak = now - stillStartMs;
    drawScreen(redOn ? "MOVED!" : "still", currentStreak, bestStreakMs);
  }

  delay(10);
}

// Storm Glass - barometric trend forecaster on an OLED
//
// Hardware: ESP32 NodeMCU-32S + GY-BMP280 + 0.96" SSD1306 OLED, all on one I2C bus.
//
// What it does:
//   - Reads pressure (hPa) from the BMP280 once per second.
//   - Keeps a rolling 3-hour history (one sample per minute) in RAM.
//   - Every second draws: current pressure, temperature, a big trend arrow
//     (up / flat / down), and a one-word forecast based on the 3-hour delta.
//
// Forecast rules of thumb that meteorologists actually use:
//   - Pressure rising > +1.0 hPa / 3 h .... clearing / fair
//   - Pressure steady within +-1.0 hPa .... no change
//   - Pressure falling < -1.0 hPa / 3 h ... rain / storm likely
//   - Falling fast (< -3.0 hPa / 3 h) ..... storm warning
//
// Wiring (matches the Mermaid diagram):
//   ESP32 3V3 -> BMP280 VCC, OLED VCC
//   ESP32 GND -> BMP280 GND, OLED GND
//   ESP32 GPIO21 (SDA) -> BMP280 SDA, OLED SDA
//   ESP32 GPIO22 (SCL) -> BMP280 SCL, OLED SCL
//
// Library install (Arduino IDE -> Library Manager):
//   - "Adafruit BMP280 Library" (also pulls Adafruit BusIO + Adafruit Unified Sensor)
//   - "Adafruit SSD1306"        (also pulls Adafruit GFX)

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_BMP280.h>

// ---------- pins ----------
// ESP32 default I2C pins. Both modules sit on this same bus.
static const int PIN_SDA = 21;
static const int PIN_SCL = 22;

// ---------- I2C addresses ----------
// GY-BMP280 clones are usually at 0x76 (SDO tied low). A few are at 0x77.
// If begin() fails at 0x76 we try 0x77 automatically.
static const uint8_t BMP280_ADDR_PRIMARY   = 0x76;
static const uint8_t BMP280_ADDR_SECONDARY = 0x77;

// 128x64 SSD1306 OLED, typically at 0x3C.
static const uint8_t OLED_ADDR    = 0x3C;
static const int     OLED_WIDTH   = 128;
static const int     OLED_HEIGHT  = 64;
static const int     OLED_RESET   = -1;   // share ESP32 reset

Adafruit_BMP280 bmp;                       // I2C
Adafruit_SSD1306 oled(OLED_WIDTH, OLED_HEIGHT, &Wire, OLED_RESET);

// ---------- history buffer ----------
// One pressure sample per minute, 180 minutes = 3 hours.
static const int HISTORY_MINUTES = 180;
float history[HISTORY_MINUTES];
int   historyCount = 0;       // how many slots are valid (grows to HISTORY_MINUTES)
int   historyHead  = 0;       // next index to write

unsigned long lastSampleMs   = 0;   // last time we appended to history
unsigned long lastDisplayMs  = 0;   // last time we redrew

// ---------- helpers ----------
void recordSample(float hPa) {
  history[historyHead] = hPa;
  historyHead = (historyHead + 1) % HISTORY_MINUTES;
  if (historyCount < HISTORY_MINUTES) historyCount++;
}

// Return the oldest valid sample (~ "3 hours ago" once buffer is full).
// If we have fewer than 2 samples, return NaN so the caller knows.
float oldestSample() {
  if (historyCount < 2) return NAN;
  // Oldest slot is the one we are about to overwrite once buffer is full,
  // otherwise it is index 0.
  int oldestIdx = (historyCount < HISTORY_MINUTES) ? 0 : historyHead;
  return history[oldestIdx];
}

// Forecast word + arrow character (drawn as text glyphs we shape ourselves).
struct Forecast {
  const char *word;
  int   arrow;   // -2 fast down, -1 down, 0 steady, +1 up, +2 fast up
};

Forecast classify(float deltaHPa) {
  if (isnan(deltaHPa))      return { "Warming up", 0 };
  if (deltaHPa <= -3.0f)    return { "Storm!",     -2 };
  if (deltaHPa <= -1.0f)    return { "Rain likely",-1 };
  if (deltaHPa >=  3.0f)    return { "Fair fast",  +2 };
  if (deltaHPa >=  1.0f)    return { "Clearing",   +1 };
  return                          { "Steady",       0 };
}

// Draw a chunky arrow (or flat bar) centred in a 40x40 box at (x,y).
void drawArrow(int x, int y, int dir) {
  const int W = 40, H = 40;
  if (dir == 0) {
    // flat bar
    oled.fillRect(x + 4, y + H/2 - 3, W - 8, 6, SSD1306_WHITE);
    return;
  }
  bool up   = dir > 0;
  bool fast = (dir == 2 || dir == -2);

  // shaft
  oled.fillRect(x + W/2 - 3, y + 6, 6, H - 12, SSD1306_WHITE);
  // arrowhead (triangle)
  if (up) {
    oled.fillTriangle(x + W/2,        y,
                      x + 4,          y + 14,
                      x + W - 4,      y + 14, SSD1306_WHITE);
  } else {
    oled.fillTriangle(x + W/2,        y + H,
                      x + 4,          y + H - 14,
                      x + W - 4,      y + H - 14, SSD1306_WHITE);
  }
  // double arrow head for "fast" categories
  if (fast) {
    if (up) {
      oled.fillTriangle(x + W/2,    y + 10,
                        x + 6,      y + 22,
                        x + W - 6,  y + 22, SSD1306_WHITE);
    } else {
      oled.fillTriangle(x + W/2,    y + H - 10,
                        x + 6,      y + H - 22,
                        x + W - 6,  y + H - 22, SSD1306_WHITE);
    }
  }
}

void drawScreen(float pressureHPa, float tempC, float deltaHPa) {
  Forecast f = classify(deltaHPa);

  oled.clearDisplay();

  // Top line: pressure in big text
  oled.setTextColor(SSD1306_WHITE);
  oled.setTextSize(2);
  oled.setCursor(0, 0);
  oled.print(pressureHPa, 1);
  oled.setTextSize(1);
  oled.print(" hPa");

  // Second line: temperature
  oled.setTextSize(1);
  oled.setCursor(0, 20);
  oled.print("T: ");
  oled.print(tempC, 1);
  oled.print((char)247);   // degree symbol in default font
  oled.print("C");

  // Arrow on the right
  drawArrow(88, 22, f.arrow);

  // Bottom area: delta + forecast word
  oled.setCursor(0, 36);
  oled.print("3h delta: ");
  if (!isnan(deltaHPa)) {
    if (deltaHPa >= 0) oled.print('+');
    oled.print(deltaHPa, 1);
    oled.print(" hPa");
  } else {
    oled.print("--");
  }

  oled.setTextSize(2);
  oled.setCursor(0, 48);
  oled.print(f.word);

  oled.display();
}

// Try BMP280 at 0x76 then 0x77. Returns true if found.
bool initBmp280() {
  if (bmp.begin(BMP280_ADDR_PRIMARY))   return true;
  if (bmp.begin(BMP280_ADDR_SECONDARY)) return true;
  return false;
}

void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("Storm Glass starting...");

  Wire.begin(PIN_SDA, PIN_SCL);

  // OLED first so we can show errors on it.
  if (!oled.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("OLED not found at 0x3C - check wiring.");
    while (true) { delay(1000); }
  }
  oled.clearDisplay();
  oled.setTextColor(SSD1306_WHITE);
  oled.setTextSize(1);
  oled.setCursor(0, 0);
  oled.println("Storm Glass");
  oled.println("booting...");
  oled.display();

  if (!initBmp280()) {
    oled.clearDisplay();
    oled.setCursor(0, 0);
    oled.println("BMP280 not found");
    oled.println("Check SDA/SCL/VCC");
    oled.display();
    Serial.println("BMP280 not found at 0x76 or 0x77.");
    while (true) { delay(1000); }
  }

  // Recommended indoor weather settings from the datasheet:
  // x16 oversampling on pressure, x2 on temperature, IIR x16, 0.5 ms standby.
  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL,
                  Adafruit_BMP280::SAMPLING_X2,
                  Adafruit_BMP280::SAMPLING_X16,
                  Adafruit_BMP280::FILTER_X16,
                  Adafruit_BMP280::STANDBY_MS_500);

  // Seed the history with the current reading so the first display has something.
  recordSample(bmp.readPressure() / 100.0f);
  lastSampleMs = millis();
}

void loop() {
  unsigned long now = millis();

  // Update screen every 1 second.
  if (now - lastDisplayMs >= 1000) {
    lastDisplayMs = now;

    float pressureHPa = bmp.readPressure() / 100.0f;  // Pa -> hPa
    float tempC       = bmp.readTemperature();

    float oldest = oldestSample();
    float delta  = isnan(oldest) ? NAN : (pressureHPa - oldest);

    drawScreen(pressureHPa, tempC, delta);

    Serial.print("P=");  Serial.print(pressureHPa, 2);
    Serial.print(" hPa  T=");  Serial.print(tempC, 2);
    Serial.print(" C  d3h=");
    if (!isnan(delta)) Serial.print(delta, 2); else Serial.print("NaN");
    Serial.println(" hPa");
  }

  // Append one sample to history every 60 seconds.
  if (now - lastSampleMs >= 60000UL) {
    lastSampleMs = now;
    recordSample(bmp.readPressure() / 100.0f);
  }
}

// Battery Health OLED Monitor
// Reads a low-voltage DC source through the Voltage Sensor Module (5:1 divider)
// and shows live voltage, a bar graph, and a status word on the OLED.
// A green LED lights when voltage looks "healthy"; a red LED warns when low.
//
// Board: ESP32 NodeMCU-32S
// Libraries (install in Arduino IDE Library Manager):
//   - Adafruit GFX Library
//   - Adafruit SSD1306
//
// SAFETY: never feed more than 25V DC into the voltage module.
//         The module is DC-only. No AC. No mains. Common-ground with the ESP32.
//
// IMPORTANT ADC RANGE NOTE:
//   The ESP32 ADC with 11dB attenuation only stays linear from ~150mV up to
//   about ~2.45V at the pin. After the 5:1 divider that means inputs up to
//   roughly ~12V read accurately; above that the ADC starts to clip/saturate
//   and the number on screen will plateau. The module itself can take 25V
//   without damage, but the displayed voltage above ~12V is not trustworthy.
//   For everyday batteries (single 9V, 18650, 12V SLA at rest ~12.6V) this
//   is fine. Calibrate CAL against a multimeter inside the band you care about
//   (e.g. 6-10V for 9V alkalines).

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ---- pins ----
const int PIN_VSENSE = 34;   // ADC1_CH6, input-only, safe for analog reads
const int PIN_LED_GREEN = 25;
const int PIN_LED_RED   = 26;

// ---- OLED ----
#define OLED_WIDTH   128
#define OLED_HEIGHT  64
#define OLED_ADDR    0x3C
Adafruit_SSD1306 oled(OLED_WIDTH, OLED_HEIGHT, &Wire, -1);

// ---- voltage divider math ----
// The module has a built-in 30k + 7.5k divider, ratio 5.0 (Vin = Vout * 5).
// We feed Vout into ADC pin 34. With ADC_11db attenuation the ADC nominally
// spans 0-3.3V, but in practice only ~0.15V to ~2.45V is linear. The CAL
// fudge factor lets Andy nudge the displayed number to match a multimeter
// in the voltage band he actually cares about.
const float ADC_REF_VOLTS  = 3.30f;
const float ADC_MAX_COUNTS = 4095.0f;     // 12-bit
const float DIVIDER_RATIO  = 5.00f;       // module's printed ratio
const float CAL            = 1.00f;       // tweak after measuring with a meter

// Highest input voltage the ADC can still read linearly (with the 5:1 divider).
const float LINEAR_MAX_VIN = 12.0f;

// "Healthy" threshold - example tuned for a 9V alkaline battery.
// 9V fresh ~ 9.5V, "tired" by ~7.0V, dead by ~5.5V.
const float HEALTHY_VOLTS = 7.00f;

// Smoothing: average N samples to calm the ADC jitter.
const int SAMPLES = 32;

float readVoltage() {
    long acc = 0;
    for (int i = 0; i < SAMPLES; i++) {
        acc += analogRead(PIN_VSENSE);
        delayMicroseconds(200);
    }
    float counts = (float)acc / (float)SAMPLES;
    float vAtPin = (counts / ADC_MAX_COUNTS) * ADC_REF_VOLTS;
    float vIn = vAtPin * DIVIDER_RATIO * CAL;
    if (vIn < 0.0f) vIn = 0.0f;
    return vIn;
}

void drawScreen(float volts, bool overRange) {
    oled.clearDisplay();

    // Title
    oled.setTextSize(1);
    oled.setTextColor(SSD1306_WHITE);
    oled.setCursor(0, 0);
    oled.print("Battery Monitor");

    // Big voltage number
    oled.setTextSize(2);
    oled.setCursor(0, 14);
    oled.print(volts, 2);
    oled.print("V");

    // Status word
    oled.setTextSize(1);
    oled.setCursor(0, 36);
    if (overRange) {
        oled.print("Status: >12V (clip)");
    } else if (volts >= HEALTHY_VOLTS) {
        oled.print("Status: HEALTHY");
    } else if (volts >= 5.5f) {
        oled.print("Status: LOW");
    } else {
        oled.print("Status: DEAD");
    }

    // Bar graph along the bottom, full scale = LINEAR_MAX_VIN
    int barMax = OLED_WIDTH - 4;
    int barLen = (int)((volts / LINEAR_MAX_VIN) * barMax);
    if (barLen < 0) barLen = 0;
    if (barLen > barMax) barLen = barMax;
    oled.drawRect(0, 50, OLED_WIDTH, 12, SSD1306_WHITE);
    oled.fillRect(2, 52, barLen, 8, SSD1306_WHITE);

    oled.display();
}

void setup() {
    Serial.begin(115200);
    delay(200);
    Serial.println();
    Serial.println("Battery Health OLED Monitor booting...");

    pinMode(PIN_LED_GREEN, OUTPUT);
    pinMode(PIN_LED_RED, OUTPUT);
    digitalWrite(PIN_LED_GREEN, LOW);
    digitalWrite(PIN_LED_RED, LOW);

    // ADC config: 12-bit, full 0-3.3V nominal range (linear ~0.15V to ~2.45V)
    analogReadResolution(12);
    analogSetPinAttenuation(PIN_VSENSE, ADC_11db);

    Wire.begin();  // ESP32 default SDA=21, SCL=22
    if (!oled.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
        Serial.println("OLED not found at 0x3C - halting");
        while (true) { delay(1000); }
    }
    oled.clearDisplay();
    oled.setTextColor(SSD1306_WHITE);
    oled.setTextSize(1);
    oled.setCursor(0, 0);
    oled.println("Battery Monitor");
    oled.println("warming up...");
    oled.display();
    delay(500);
}

void loop() {
    float v = readVoltage();
    bool overRange = (v >= LINEAR_MAX_VIN);

    // Update LEDs
    if (!overRange && v >= HEALTHY_VOLTS) {
        digitalWrite(PIN_LED_GREEN, HIGH);
        digitalWrite(PIN_LED_RED, LOW);
    } else {
        digitalWrite(PIN_LED_GREEN, LOW);
        digitalWrite(PIN_LED_RED, HIGH);
    }

    drawScreen(v, overRange);

    Serial.print("V = ");
    Serial.print(v, 3);
    Serial.print(" V");
    if (overRange) Serial.print("  (over linear range - clipped)");
    Serial.println();

    delay(200);
}

// Raindrop Reporter
// Reads the Raindrop Sensor's analog output, classifies it as
// Dry / Misty / Wet / Soaked, shows live numbers on the OLED,
// and lights a blue LED while rain is detected.
//
// Wiring (matches the diagram):
//   Raindrop module  VCC -> ESP32 3V3
//   Raindrop module  GND -> ESP32 GND
//   Raindrop module  AO  -> ESP32 GPIO34 (ADC1, input-only - safe)
//   OLED  VCC -> 3V3, GND -> GND, SDA -> GPIO21, SCL -> GPIO22
//   LED anode -> 330R -> GPIO5,  LED cathode -> GND
//
// Quirk: the raindrop module is "wet = low value, dry = high value".
// Dry air typically reads near 4095; water shorts the comb traces and
// pulls the reading down toward 0.

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET   -1
#define OLED_ADDR    0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

const int RAIN_PIN = 34;   // analog input from sensor AO
const int LED_PIN  = 5;    // blue LED via 330R

// Thresholds tuned for a 3.3V supply and a 12-bit ADC (0..4095).
// Higher number = drier. Tweak these once you watch the live values.
const int SOAKED_BELOW = 1200;
const int WET_BELOW    = 2400;
const int MISTY_BELOW  = 3600;
// Anything >= MISTY_BELOW counts as Dry.

const char* classify(int v) {
  if (v < SOAKED_BELOW) return "SOAKED";
  if (v < WET_BELOW)    return "WET";
  if (v < MISTY_BELOW)  return "MISTY";
  return "DRY";
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  Wire.begin(21, 22);  // SDA, SCL
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("OLED not found - check wiring / address");
    while (true) { delay(1000); }
  }

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println("Raindrop Reporter");
  display.println("warming up...");
  display.display();
  delay(800);
}

void loop() {
  // Average a few samples so a single noisy reading doesn't make
  // the display flicker between states.
  long sum = 0;
  const int N = 8;
  for (int i = 0; i < N; i++) {
    sum += analogRead(RAIN_PIN);
    delay(5);
  }
  int raw = sum / N;

  const char* state = classify(raw);
  bool isRaining = (raw < MISTY_BELOW);
  digitalWrite(LED_PIN, isRaining ? HIGH : LOW);

  // Percent "wetness" for the bar - invert so wet = full bar.
  int wetness = map(raw, 0, 4095, 100, 0);
  if (wetness < 0)   wetness = 0;
  if (wetness > 100) wetness = 100;

  display.clearDisplay();

  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("Raindrop Reporter");

  display.setTextSize(2);
  display.setCursor(0, 14);
  display.print(state);

  display.setTextSize(1);
  display.setCursor(0, 36);
  display.print("raw: ");
  display.print(raw);
  display.print("/4095");

  // Wetness bar
  display.drawRect(0, 50, 128, 10, SSD1306_WHITE);
  int fill = (wetness * 124) / 100;
  display.fillRect(2, 52, fill, 6, SSD1306_WHITE);

  display.display();

  Serial.printf("raw=%d  state=%s  wet=%d%%\n", raw, state, wetness);
  delay(250);
}

// Tub Filler Traffic Light
// Arduino Uno R3 + Water Level Sensor + LCD 1602 I2C + 3 LEDs
//
// Dip the sensor into a glass of water. The LCD shows a live bar graph
// and a percent. Three LEDs light up in sequence as the water rises:
//   - Red  (D5): even a drop touches the combs
//   - Yellow (D6): about half-full
//   - Green (D7): full
//
// Wiring:
//   Sensor:  + -> 5V,  - -> GND,  S -> A0   (1M pull-down from A0 to GND)
//   LCD I2C: VCC -> 5V, GND -> GND, SDA -> A4, SCL -> A5
//   LEDs:    D5/D6/D7 -> 330R -> LED anode; cathode -> GND
//
// Library to install once via Arduino IDE Library Manager:
//   "LiquidCrystal I2C" by Frank de Brabander (or any compatible fork).

#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Most cheap I2C backpacks live at 0x27. If yours shows a blank screen,
// try 0x3F.
LiquidCrystal_I2C lcd(0x27, 16, 2);

const uint8_t SENSOR_PIN = A0;
const uint8_t RED_PIN    = 5;
const uint8_t YELLOW_PIN = 6;
const uint8_t GREEN_PIN  = 7;

// Calibration. DRY_MIN should be roughly what you see in the Serial
// Monitor when the sensor is bone-dry (with the 1M pull-down it should
// be near 0). WET_MAX is what you see when the comb is fully submerged
// in tap water - typically 500-700. Re-tune both once you've watched
// real readings come in.
const int DRY_MIN = 0;
const int WET_MAX = 600;

// Thresholds expressed as percent of full.
const int RED_AT    = 5;   // any droplet at all
const int YELLOW_AT = 40;  // about half
const int GREEN_AT  = 80;  // basically full

// Custom characters that let us draw a smooth 16-cell bar graph using
// LCD rows. Each char fills 1, 2, 3, 4, or 5 vertical bars of one cell.
byte bar1[8] = {0x10,0x10,0x10,0x10,0x10,0x10,0x10,0x10};
byte bar2[8] = {0x18,0x18,0x18,0x18,0x18,0x18,0x18,0x18};
byte bar3[8] = {0x1C,0x1C,0x1C,0x1C,0x1C,0x1C,0x1C,0x1C};
byte bar4[8] = {0x1E,0x1E,0x1E,0x1E,0x1E,0x1E,0x1E,0x1E};
byte bar5[8] = {0x1F,0x1F,0x1F,0x1F,0x1F,0x1F,0x1F,0x1F};

void setup() {
  Serial.begin(115200);

  pinMode(RED_PIN, OUTPUT);
  pinMode(YELLOW_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  digitalWrite(RED_PIN, LOW);
  digitalWrite(YELLOW_PIN, LOW);
  digitalWrite(GREEN_PIN, LOW);

  lcd.init();
  lcd.backlight();
  lcd.createChar(1, bar1);
  lcd.createChar(2, bar2);
  lcd.createChar(3, bar3);
  lcd.createChar(4, bar4);
  lcd.createChar(5, bar5);

  lcd.setCursor(0, 0);
  lcd.print("Tub Filler");
  lcd.setCursor(0, 1);
  lcd.print("Dip the sensor..");
  delay(1500);
  lcd.clear();
}

// Smooth a few readings together so the bar graph doesn't jitter.
int readLevelRaw() {
  long sum = 0;
  const int N = 8;
  for (int i = 0; i < N; i++) {
    sum += analogRead(SENSOR_PIN);
    delay(2);
  }
  return (int)(sum / N);
}

void drawBar(int percent) {
  // 16 cells across, each cell shows 0..5 sub-bars, so 80 sub-bars total.
  int totalSubBars = map(percent, 0, 100, 0, 80);
  if (totalSubBars < 0) totalSubBars = 0;
  if (totalSubBars > 80) totalSubBars = 80;

  int fullCells = totalSubBars / 5;
  int remainder = totalSubBars % 5;

  lcd.setCursor(0, 1);
  for (int i = 0; i < 16; i++) {
    if (i < fullCells) {
      lcd.write((uint8_t)5);
    } else if (i == fullCells && remainder > 0) {
      lcd.write((uint8_t)remainder); // 1..4
    } else {
      lcd.print(' ');
    }
  }
}

void loop() {
  int raw = readLevelRaw();

  // Clamp into the calibrated band, then convert to percent.
  int clamped = raw;
  if (clamped < DRY_MIN) clamped = DRY_MIN;
  if (clamped > WET_MAX) clamped = WET_MAX;
  int percent = map(clamped, DRY_MIN, WET_MAX, 0, 100);

  // Traffic light. Each tier is cumulative: green also leaves red and
  // yellow on, so you get a "stack" of indicators.
  digitalWrite(RED_PIN,    percent >= RED_AT    ? HIGH : LOW);
  digitalWrite(YELLOW_PIN, percent >= YELLOW_AT ? HIGH : LOW);
  digitalWrite(GREEN_PIN,  percent >= GREEN_AT  ? HIGH : LOW);

  // Top row: numeric readout. Pad to a fixed width so old digits don't
  // linger. Single-pass: figure out how many leading spaces we need.
  lcd.setCursor(0, 0);
  lcd.print("Level: ");
  int pad = (percent < 10) ? 2 : (percent < 100) ? 1 : 0;
  for (int i = 0; i < pad; i++) lcd.print(' ');
  lcd.print(percent);
  lcd.print("%   ");

  // Bottom row: the bar graph.
  drawBar(percent);

  // Also stream to Serial Monitor so we can calibrate WET_MAX.
  Serial.print("raw=");
  Serial.print(raw);
  Serial.print("  percent=");
  Serial.println(percent);

  delay(100);
}
